INSERT INTO public.crops (crop_name, acreage, description, image_url, slug, name_en, name_te, scientific_name, source_pdf_name, profile, updated_at)
INSERT INTO public.crop_varieties (crop_id, variety, duration, expected_yield, special_features, image_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Telangana Sona (RNR 15048)', '120-125 days', '25-30 q/acre', 'Fine grain, low glycemic index, blast tolerant, suitable for Telangana conditions', '/images/paddy.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Bathukamma (JGL 18047)', '125 days', '28-32 q/acre', 'Fine grain, good cooking quality, non-lodging type', '/images/paddy.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Samba Mahsuri (BPT 5204)', '145-150 days', '25-30 q/acre', 'Popular fine grain, needs careful disease management', '/images/paddy.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'MTU 1010', '120-125 days', '25-32 q/acre', 'Short duration, suitable where water is limited', '/images/paddy.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'JGL 24423', '130-135 days', '28-34 q/acre', 'High yielding fine grain variety for irrigated ecology', '/images/paddy.jpg');
INSERT INTO public.crop_production (crop_id, category, description_en, description_te) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Soil', 'Use level fields with bunds; avoid fields with severe salinity or alkalinity.', 'సమతలంగా ఉన్న పొలాలు, బలమైన మెట్లు ఉండాలి; అధిక చౌడు లేదా క్షార భూములు నివారించాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Land Preparation', 'Puddle thoroughly for transplanted paddy; for direct seeded rice prepare a fine, firm seedbed.', 'నాట్ల వరికి మట్టిని బాగా కలియదున్నాలి; నేరుగా విత్తే పద్ధతికి మెత్తని గట్టి విత్తన మడిని సిద్ధం చేయాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Nursery', 'Use clean seed, raised nursery beds and avoid over-aged seedlings.', 'శుభ్రమైన విత్తనం, ఎత్తైన నారు మడులు వాడి, ముదురు నారు వాడకూడదు.'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Harvest', 'Drain water 7-10 days before harvest and dry grain to safe moisture.', 'కోతకు 7-10 రోజుల ముందు నీరు వదిలి, ధాన్యాన్ని సురక్షిత తేమ వరకు ఆరబెట్టాలి.');
INSERT INTO public.crop_fertilizers (crop_id, stage, fertilizer, quantity, method, description_te) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Basal', 'DAP + MOP + FYM', 'As per soil test; full P and K basally', 'Incorporate before transplanting', 'వరిలో Basal దశలో DAP + MOP + FYMను సిఫారసు ప్రకారం వాడాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Tillering', 'Urea', '1/3 nitrogen', 'Broadcast on moist soil after draining excess water', 'వరిలో Tillering దశలో Ureaను సిఫారసు ప్రకారం వాడాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Panicle initiation', 'Urea', '1/3 nitrogen', 'Top dress with shallow water', 'వరిలో Panicle initiation దశలో Ureaను సిఫారసు ప్రకారం వాడాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Micronutrient correction', 'Zinc sulphate', '20 kg/ha where deficient', 'Basal or foliar correction as advisory', 'వరిలో Micronutrient correction దశలో Zinc sulphateను సిఫారసు ప్రకారం వాడాలి.');
INSERT INTO public.crop_irrigation (crop_id, stage, recommendation_en, recommendation_te) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Establishment', 'Maintain shallow water after seedling establishment; avoid deep submergence.', 'వరి పంటలో Establishment దశలో తేమ ఒత్తిడి రాకుండా చూడాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Tillering', 'Alternate wetting and drying is suitable where fields are level and water control is possible.', 'వరి పంటలో Tillering దశలో తేమ ఒత్తిడి రాకుండా చూడాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Flowering', 'Do not allow moisture stress from panicle initiation to grain filling.', 'వరి పంటలో Flowering దశలో తేమ ఒత్తిడి రాకుండా చూడాలి.');
INSERT INTO public.crop_weeds (crop_id, scientific_name, weed_name, control_measure, herbicide, dose, image_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Echinochloa crus-galli', 'Barnyard grass', 'Early flooding, line planting and hand weeding', 'Pretilachlor 50 EC', '500 ml/acre within 3-5 DAT', '/images/paddy.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Cyperus difformis', 'Smallflower umbrella sedge', 'Maintain shallow water and remove before seed set', 'Bensulfuron methyl + Pretilachlor', 'Recommended label dose', '/images/paddy.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Monochoria vaginalis', 'Pickerel weed', 'Hand weeding and stale seedbed', '2,4-D sodium salt', 'Use after crop establishment', '/images/paddy.jpg');
INSERT INTO public.crop_pests (crop_id, pest_name, scientific_name, symptoms, management, chemical_control, image_url, image_source_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Brown planthopper', 'Nilaparvata lugens', 'Nymphs and adults suck sap at plant base; hopper burn patches appear.', 'Avoid excess nitrogen, drain briefly, conserve predators and spray above ETL.', 'Pymetrozine 50 WG or Dinotefuran 20 SG as local advisory', 'https://agritech.tnau.ac.in/crop_protection/rice/images/pestc/ricenew/BPH/bph%20damage.jpg', 'https://agritech.tnau.ac.in/expert_system/paddy/cppests_SB.html'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Yellow stem borer', 'Scirpophaga incertulas', 'Dead heart at vegetative stage and white ear at reproductive stage.', 'Clip seedling tips, remove stubbles, use pheromone traps and need-based insecticide.', 'Chlorantraniliprole 18.5 SC or Cartap hydrochloride', 'https://agritech.tnau.ac.in/crop_protection/images/pestc/ricenew/stemborer/deadheart.jpg', 'https://agritech.tnau.ac.in/expert_system/paddy/cppests_SB.html');
INSERT INTO public.crop_diseases (crop_id, disease_name, causal_organism, symptoms, management, fungicide, image_url, image_source_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Blast', 'Magnaporthe oryzae / Pyricularia oryzae', 'Spindle-shaped grey lesions with brown margins; neck blast causes chaffy grains.', 'Use clean seed, balanced nitrogen, tolerant varieties and avoid dense canopy.', 'Tricyclazole 75 WP or Azoxystrobin + Difenoconazole', 'https://agritech.tnau.ac.in/ta/crop_protection/images/crop_diseases/paddy/Blast_sym1.JPG', 'https://www.agritech.tnau.ac.in/expert_system/paddy/cpdisblast.html'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Sheath blight', 'Rhizoctonia solani', 'Oval lesions on sheath near water line that spread upward.', 'Avoid excess nitrogen, maintain spacing and improve aeration.', 'Hexaconazole or Validamycin as recommended', '/images/paddy.jpg', 'PJTAU crop PDFs supplied by user: F:/pjtsau crops');
INSERT INTO public.crop_deficiencies (crop_id, deficiency_name, nutrient, symptoms, correction, image_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Zinc deficiency', 'Zinc', 'Bronzing, stunted plants and uneven growth patches.', 'Apply zinc sulphate to soil or foliar spray based on severity.', 'https://www.knowledgebank.irri.org/images/stories/rice-nutrient-disorders/zinc-deficiency-rice.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Nitrogen deficiency', 'Nitrogen', 'Older leaves turn pale yellow and tillering reduces.', 'Apply split nitrogen after confirming no waterlogging stress.', '/images/paddy.jpg');
INSERT INTO public.crop_advisories (crop_id, category, advisory_en, advisory_te, keywords) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Pre-sowing', 'Collect soil sample and plan fertilizer from soil-test values.', 'విత్తే ముందు నేల నమూనా తీసుకుని పరీక్ష ఆధారంగా ఎరువుల ప్రణాళిక చేయాలి.', ARRAY['paddy', 'pre-sowing', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Seed treatment', 'Nursery seed 20-25 kg/acre; direct seeded rice 10-12 kg/acre. Treat seed with carbendazim or recommended bioagent and use salt-water seed selection where practiced.', 'విత్తన శుద్ధి తప్పనిసరిగా చేసి వరి పంటను ఆరోగ్యంగా ప్రారంభించాలి.', ARRAY['paddy', 'seed treatment', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'Weather risk', 'Do not spray pesticides during high wind, rain or peak heat.', 'గాలి ఎక్కువగా ఉన్నప్పుడు, వర్షం ఉన్నప్పుడు లేదా తీవ్రమైన ఎండలో మందులు పిచికారీ చేయకూడదు.', ARRAY['paddy', 'weather risk', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'IPM', 'Use cultural, mechanical and biological measures before chemical control.', 'రసాయన నియంత్రణకు ముందు సాగు, యాంత్రిక, జీవ నియంత్రణ పద్ధతులు పాటించాలి.', ARRAY['paddy', 'ipm', 'advisory']::text[]);
INSERT INTO public.crop_faqs (crop_id, question, answer, answer_te, category, keywords) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should I check this week? What is the best production system for Paddy / Rice?', 'Raise healthy nursery, transplant young seedlings, maintain optimum plant population, use balanced nutrients and timely weed and pest monitoring.', 'వరి: పంట వివరాలు విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Crop Profile', ARRAY['profile', 'production', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should I check this week? Which soil is suitable for Paddy / Rice?', 'Clay loams and water-retentive fertile soils are preferred. Avoid saline, alkaline and poorly drained problem soils unless reclaimed.', 'వరి: నేల విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Soil', ARRAY['soil', 'land', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should I check this week? What climate does Paddy / Rice need?', 'Warm humid climate with reliable irrigation or rainfall. Sensitive to cold during flowering and grain filling.', 'వరి: వాతావరణం విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Climate', ARRAY['climate', 'weather', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should I check this week? What is the seed rate for Paddy / Rice?', 'Nursery seed 20-25 kg/acre; direct seeded rice 10-12 kg/acre. Treat seed with carbendazim or recommended bioagent and use salt-water seed selection where practiced.', 'వరి: విత్తనం విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Seed', ARRAY['seed rate', 'seed treatment', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should I check this week? When and how should Paddy / Rice be sown?', 'Nursery from late May to July based on water availability. Transplant at 20 x 15 cm or use line sowing in direct seeded fields after puddling or fine seedbed preparation.', 'వరి: విత్తడం విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Sowing', ARRAY['sowing', 'spacing', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should I check this week? How should fertilizer be applied in Paddy / Rice?', 'Basal: DAP + MOP + FYM As per soil test; full P and K basally; Tillering: Urea 1/3 nitrogen; Panicle initiation: Urea 1/3 nitrogen; Micronutrient correction: Zinc sulphate 20 kg/ha where deficient', 'వరి: ఎరువులు విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Fertilizer', ARRAY['fertilizer', 'nutrients', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should I check this week? What are critical irrigation stages for Paddy / Rice?', 'Establishment: Maintain shallow water after seedling establishment; avoid deep submergence. Tillering: Alternate wetting and drying is suitable where fields are level and water control is possible. Flowering: Do not allow moisture stress from panicle initiation to grain filling.', 'వరి: నీటి నిర్వహణ విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Irrigation', ARRAY['irrigation', 'water', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should I check this week? How are weeds managed in Paddy / Rice?', 'Barnyard grass: Early flooding, line planting and hand weeding; Smallflower umbrella sedge: Maintain shallow water and remove before seed set; Pickerel weed: Hand weeding and stale seedbed', 'వరి: కలుపు విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Weed', ARRAY['weed', 'herbicide', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should I check this week? Which major pests attack Paddy / Rice?', 'Brown planthopper: Nymphs and adults suck sap at plant base; hopper burn patches appear. Management: Avoid excess nitrogen, drain briefly, conserve predators and spray above ETL. Yellow stem borer: Dead heart at vegetative stage and white ear at reproductive stage. Management: Clip seedling tips, remove stubbles, use pheromone traps and need-based insecticide.', 'వరి: పురుగులు విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Pest', ARRAY['pest', 'ipm', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should I check this week? Which diseases are important in Paddy / Rice?', 'Blast: Spindle-shaped grey lesions with brown margins; neck blast causes chaffy grains. Management: Use clean seed, balanced nitrogen, tolerant varieties and avoid dense canopy. Sheath blight: Oval lesions on sheath near water line that spread upward. Management: Avoid excess nitrogen, maintain spacing and improve aeration.', 'వరి: తెగుళ్లు విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Disease', ARRAY['disease', 'fungicide', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should I check this week? What nutrient deficiencies are common in Paddy / Rice?', 'Zinc deficiency: Bronzing, stunted plants and uneven growth patches. Correction: Apply zinc sulphate to soil or foliar spray based on severity. Nitrogen deficiency: Older leaves turn pale yellow and tillering reduces. Correction: Apply split nitrogen after confirming no waterlogging stress.', 'వరి: లోప లక్షణాలు విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Deficiency', ARRAY['deficiency', 'nutrient', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should I check this week? When should Paddy / Rice be harvested?', 'Harvest when 80-85% grains are mature and straw turns yellow. Expected yield is 25-35 q/acre depending on variety and water management.', 'వరి: కోత విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Harvest', ARRAY['harvest', 'yield', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should an Agriculture Officer advise? What is the best production system for Paddy / Rice?', 'Raise healthy nursery, transplant young seedlings, maintain optimum plant population, use balanced nutrients and timely weed and pest monitoring.', 'వరి: పంట వివరాలు విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Crop Profile', ARRAY['profile', 'production', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should an Agriculture Officer advise? Which soil is suitable for Paddy / Rice?', 'Clay loams and water-retentive fertile soils are preferred. Avoid saline, alkaline and poorly drained problem soils unless reclaimed.', 'వరి: నేల విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Soil', ARRAY['soil', 'land', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should an Agriculture Officer advise? What climate does Paddy / Rice need?', 'Warm humid climate with reliable irrigation or rainfall. Sensitive to cold during flowering and grain filling.', 'వరి: వాతావరణం విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Climate', ARRAY['climate', 'weather', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should an Agriculture Officer advise? What is the seed rate for Paddy / Rice?', 'Nursery seed 20-25 kg/acre; direct seeded rice 10-12 kg/acre. Treat seed with carbendazim or recommended bioagent and use salt-water seed selection where practiced.', 'వరి: విత్తనం విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Seed', ARRAY['seed rate', 'seed treatment', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should an Agriculture Officer advise? When and how should Paddy / Rice be sown?', 'Nursery from late May to July based on water availability. Transplant at 20 x 15 cm or use line sowing in direct seeded fields after puddling or fine seedbed preparation.', 'వరి: విత్తడం విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Sowing', ARRAY['sowing', 'spacing', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should an Agriculture Officer advise? How should fertilizer be applied in Paddy / Rice?', 'Basal: DAP + MOP + FYM As per soil test; full P and K basally; Tillering: Urea 1/3 nitrogen; Panicle initiation: Urea 1/3 nitrogen; Micronutrient correction: Zinc sulphate 20 kg/ha where deficient', 'వరి: ఎరువులు విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Fertilizer', ARRAY['fertilizer', 'nutrients', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should an Agriculture Officer advise? What are critical irrigation stages for Paddy / Rice?', 'Establishment: Maintain shallow water after seedling establishment; avoid deep submergence. Tillering: Alternate wetting and drying is suitable where fields are level and water control is possible. Flowering: Do not allow moisture stress from panicle initiation to grain filling.', 'వరి: నీటి నిర్వహణ విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Irrigation', ARRAY['irrigation', 'water', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should an Agriculture Officer advise? How are weeds managed in Paddy / Rice?', 'Barnyard grass: Early flooding, line planting and hand weeding; Smallflower umbrella sedge: Maintain shallow water and remove before seed set; Pickerel weed: Hand weeding and stale seedbed', 'వరి: కలుపు విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Weed', ARRAY['weed', 'herbicide', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should an Agriculture Officer advise? Which major pests attack Paddy / Rice?', 'Brown planthopper: Nymphs and adults suck sap at plant base; hopper burn patches appear. Management: Avoid excess nitrogen, drain briefly, conserve predators and spray above ETL. Yellow stem borer: Dead heart at vegetative stage and white ear at reproductive stage. Management: Clip seedling tips, remove stubbles, use pheromone traps and need-based insecticide.', 'వరి: పురుగులు విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Pest', ARRAY['pest', 'ipm', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should an Agriculture Officer advise? Which diseases are important in Paddy / Rice?', 'Blast: Spindle-shaped grey lesions with brown margins; neck blast causes chaffy grains. Management: Use clean seed, balanced nitrogen, tolerant varieties and avoid dense canopy. Sheath blight: Oval lesions on sheath near water line that spread upward. Management: Avoid excess nitrogen, maintain spacing and improve aeration.', 'వరి: తెగుళ్లు విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Disease', ARRAY['disease', 'fungicide', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should an Agriculture Officer advise? What nutrient deficiencies are common in Paddy / Rice?', 'Zinc deficiency: Bronzing, stunted plants and uneven growth patches. Correction: Apply zinc sulphate to soil or foliar spray based on severity. Nitrogen deficiency: Older leaves turn pale yellow and tillering reduces. Correction: Apply split nitrogen after confirming no waterlogging stress.', 'వరి: లోప లక్షణాలు విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Deficiency', ARRAY['deficiency', 'nutrient', 'paddy', 'paddy / rice']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Paddy'), 'What should an Agriculture Officer advise? When should Paddy / Rice be harvested?', 'Harvest when 80-85% grains are mature and straw turns yellow. Expected yield is 25-35 q/acre depending on variety and water management.', 'వరి: కోత విభాగంలో ఈ సిఫారసును పాటించాలి. నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.', 'Harvest', ARRAY['harvest', 'yield', 'paddy', 'paddy / rice']::text[]),
