INSERT INTO public.crop_production (crop_id, category, description_en, description_te) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Land Preparation', 'Prepare a fine seedbed with drainage furrows; avoid cloddy fields.', 'మురుగు నీరు పోయేలా సాళ్లు చేసి మెత్తని విత్తన మడిని సిద్ధం చేయాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Sowing', 'Place seed 4-5 cm deep in lines and maintain uniform plant stand.', 'విత్తనాన్ని 4-5 సెం.మీ. లోతులో వరుసలలో వేసి సమాన మొక్కల సంఖ్య ఉంచాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Earthing Up', 'Earth up at knee-high stage after top dressing nitrogen.', 'మోకాలి ఎత్తు దశలో నత్రజని వేసిన తరువాత మట్టిని ఎగదీయాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Harvest', 'Harvest when cobs dry and black layer forms at grain base.', 'కంకులు ఎండినప్పుడు, గింజ అడుగున బ్లాక్ లేయర్ ఏర్పడినప్పుడు కోత చేయాలి.');
INSERT INTO public.crop_fertilizers (crop_id, stage, fertilizer, quantity, method, description_te) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Basal', 'DAP + MOP + FYM', 'Full P and K; 1/3 N', 'Band placement near seed row', 'మొక్కజొన్నలో Basal దశలో DAP + MOP + FYMను సిఫారసు ప్రకారం వాడాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Knee-high', 'Urea', '1/3 nitrogen', 'Top dress followed by earthing up', 'మొక్కజొన్నలో Knee-high దశలో Ureaను సిఫారసు ప్రకారం వాడాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Tasseling', 'Urea', '1/3 nitrogen', 'Apply with irrigation or adequate soil moisture', 'మొక్కజొన్నలో Tasseling దశలో Ureaను సిఫారసు ప్రకారం వాడాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Micronutrient', 'Zinc sulphate', 'Soil-test based', 'Basal or foliar correction', 'మొక్కజొన్నలో Micronutrient దశలో Zinc sulphateను సిఫారసు ప్రకారం వాడాలి.');
INSERT INTO public.crop_irrigation (crop_id, stage, recommendation_en, recommendation_te) VALUES
