INSERT INTO public.crop_pests (crop_id, pest_name, scientific_name, symptoms, management, chemical_control, image_url, image_source_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Fall armyworm', 'Spodoptera frugiperda', 'Scraping, ragged holes, whorl feeding and frass in central whorl.', 'Install pheromone traps, destroy egg masses, direct spray into whorl at early stage.', 'Chlorantraniliprole 18.5 SC, Emamectin benzoate 5 SG or Spinetoram 11.7 SC', 'https://agritech.tnau.ac.in/crop_protection/maize/images/fallarmyworm/whorl%20damage.jpg', 'https://agritech.tnau.ac.in/crop_protection/maize/crop_prot_maize_fall_armyworm.html'),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Stem borer', 'Chilo partellus', 'Dead hearts in young crop and stem tunneling.', 'Remove affected whorls, intercrop cowpea and use need-based whorl application.', 'Chlorantraniliprole or Carbofuran granules as permitted', 'https://agritech.tnau.ac.in/crop_protection/rice/images/pestc/maize/stemfly/deadheart.jpg', 'https://agritech.tnau.ac.in/crop_protection/crop_prot_crop_insectpest%20_cereals_maizemain.html');
INSERT INTO public.crop_diseases (crop_id, disease_name, causal_organism, symptoms, management, fungicide, image_url, image_source_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Turcicum leaf blight', 'Exserohilum turcicum', 'Long grey-green cigar-shaped lesions on leaves.', 'Use tolerant hybrids and remove infected residues.', 'Mancozeb or Propiconazole as advisory', '/images/maize.jpg', 'PJTAU crop PDFs supplied by user: F:/pjtsau crops'),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Banded leaf and sheath blight', 'Rhizoctonia solani f. sp. sasakii', 'Banded lesions on sheath and lower leaves.', 'Avoid dense planting and waterlogging.', 'Validamycin or Hexaconazole as recommended', '/images/maize.jpg', 'PJTAU crop PDFs supplied by user: F:/pjtsau crops');
INSERT INTO public.crop_deficiencies (crop_id, deficiency_name, nutrient, symptoms, correction, image_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Zinc deficiency', 'Zinc', 'Broad white bands on young leaves near the base.', 'Apply zinc sulphate or foliar zinc as soil-test based correction.', '/images/maize.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Nitrogen deficiency', 'Nitrogen', 'V-shaped yellowing from tip down the midrib of older leaves.', 'Top dress nitrogen with adequate moisture.', '/images/maize.jpg');
INSERT INTO public.crop_advisories (crop_id, category, advisory_en, advisory_te, keywords) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Pre-sowing', 'Collect soil sample and plan fertilizer from soil-test values.', 'విత్తే ముందు నేల నమూనా తీసుకుని పరీక్ష ఆధారంగా ఎరువుల ప్రణాళిక చేయాలి.', ARRAY['maize', 'pre-sowing', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Seed treatment', 'Use 8-10 kg seed/acre for hybrids. Treat seed with recommended fungicide and fall armyworm seed treatment where advised.', 'విత్తన శుద్ధి తప్పనిసరిగా చేసి మొక్కజొన్న పంటను ఆరోగ్యంగా ప్రారంభించాలి.', ARRAY['maize', 'seed treatment', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'Weather risk', 'Do not spray pesticides during high wind, rain or peak heat.', 'గాలి ఎక్కువగా ఉన్నప్పుడు, వర్షం ఉన్నప్పుడు లేదా తీవ్రమైన ఎండలో మందులు పిచికారీ చేయకూడదు.', ARRAY['maize', 'weather risk', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'IPM', 'Use cultural, mechanical and biological measures before chemical control.', 'రసాయన నియంత్రణకు ముందు సాగు, యాంత్రిక, జీవ నియంత్రణ పద్ధతులు పాటించాలి.', ARRAY['maize', 'ipm', 'advisory']::text[]);
INSERT INTO public.crop_faqs (crop_id, question, answer, answer_te, category, keywords) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should I check this week? What is the best production system for Maize?', 'Direct line sowing, timely gap filling, earthing up, balanced fertilizer and early scouting for fall armyworm are essential.', 'మొక్కజొన్న: పంట వివరాలు విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Crop Profile', ARRAY['profile', 'production', 'maize', 'maize']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should I check this week? Which soil is suitable for Maize?', 'Well-drained fertile loams and red sandy loams are ideal. Waterlogging seriously reduces stand and yield.', 'మొక్కజొన్న: నేల విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Soil', ARRAY['soil', 'land', 'maize', 'maize']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should I check this week? What climate does Maize need?', 'Warm climate with good sunlight. Critical moisture stages are knee high, tasseling, silking and grain filling.', 'మొక్కజొన్న: వాతావరణం విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Climate', ARRAY['climate', 'weather', 'maize', 'maize']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should I check this week? What is the seed rate for Maize?', 'Use 8-10 kg seed/acre for hybrids. Treat seed with recommended fungicide and fall armyworm seed treatment where advised.', 'మొక్కజొన్న: విత్తనం విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Seed', ARRAY['seed rate', 'seed treatment', 'maize', 'maize']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should I check this week? When and how should Maize be sown?', 'Sow with onset of monsoon or under irrigation. Use 60 x 20 cm spacing for grain maize; prepare ridges or well-drained beds.', 'మొక్కజొన్న: విత్తడం విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Sowing', ARRAY['sowing', 'spacing', 'maize', 'maize']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should I check this week? How should fertilizer be applied in Maize?', 'Basal: DAP + MOP + FYM Full P and K; 1/3 N; Knee-high: Urea 1/3 nitrogen; Tasseling: Urea 1/3 nitrogen; Micronutrient: Zinc sulphate Soil-test based', 'మొక్కజొన్న: ఎరువులు విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Fertilizer', ARRAY['fertilizer', 'nutrients', 'maize', 'maize']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should I check this week? What are critical irrigation stages for Maize?', 'Knee-high: Give irrigation if rainfall gap occurs. Tasseling and Silking: Most critical stage; avoid stress. Grain Filling: Maintain moisture until physiological maturity.', 'మొక్కజొన్న: నీటి నిర్వహణ విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Irrigation', ARRAY['irrigation', 'water', 'maize', 'maize']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should I check this week? How are weeds managed in Maize?', 'Nut sedge: Interculture and removal of tubers where possible; Jungle rice: Early hoeing and row cultivation; Dayflower: Hand removal before rooting at nodes', 'మొక్కజొన్న: కలుపు విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Weed', ARRAY['weed', 'herbicide', 'maize', 'maize']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should I check this week? Which major pests attack Maize?', 'Fall armyworm: Scraping, ragged holes, whorl feeding and frass in central whorl. Management: Install pheromone traps, destroy egg masses, direct spray into whorl at early stage. Stem borer: Dead hearts in young crop and stem tunneling. Management: Remove affected whorls, intercrop cowpea and use need-based whorl application.', 'మొక్కజొన్న: పురుగులు విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Pest', ARRAY['pest', 'ipm', 'maize', 'maize']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should I check this week? Which diseases are important in Maize?', 'Turcicum leaf blight: Long grey-green cigar-shaped lesions on leaves. Management: Use tolerant hybrids and remove infected residues. Banded leaf and sheath blight: Banded lesions on sheath and lower leaves. Management: Avoid dense planting and waterlogging.', 'మొక్కజొన్న: తెగుళ్లు విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Disease', ARRAY['disease', 'fungicide', 'maize', 'maize']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should I check this week? What nutrient deficiencies are common in Maize?', 'Zinc deficiency: Broad white bands on young leaves near the base. Correction: Apply zinc sulphate or foliar zinc as soil-test based correction. Nitrogen deficiency: V-shaped yellowing from tip down the midrib of older leaves. Correction: Top dress nitrogen with adequate moisture.', 'మొక్కజొన్న: లోప లక్షణాలు విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Deficiency', ARRAY['deficiency', 'nutrient', 'maize', 'maize']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should I check this week? When should Maize be harvested?', 'Harvest when husk turns dry and grain moisture falls. Expected grain yield is 25-35 q/acre in good hybrids.', 'మొక్కజొన్న: కోత విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Harvest', ARRAY['harvest', 'yield', 'maize', 'maize']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should an Agriculture Officer advise? What is the best production system for Maize?', 'Direct line sowing, timely gap filling, earthing up, balanced fertilizer and early scouting for fall armyworm are essential.', 'మొక్కజొన్న: పంట వివరాలు విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Crop Profile', ARRAY['profile', 'production', 'maize', 'maize']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Maize'), 'What should an Agriculture Officer advise? Which soil is suitable for Maize?', 'Well-drained fertile loams and red sandy loams are ideal. Waterlogging seriously reduces stand and yield.', 'మొక్కజొన్న: నేల విభాగంలో ఈ సిఫారసును పాటించాలి. ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.', 'Soil', ARRAY['soil', 'land', 'maize', 'maize']::text[]),
