INSERT INTO public.crop_production (crop_id, category, description_en, description_te) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Land Preparation', 'Deep summer ploughing and broad bed furrow system improve drainage.', 'లోతుగా వేసవి దున్నకం చేసి బ్రాడ్ బెడ్ ఫరో పద్ధతి వాడితే మురుగు నీరు బాగా పోతుంది.'),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Sowing', 'Sow after sufficient rainfall and maintain one healthy plant per hill.', 'తగిన వర్షం తరువాత విత్తి ప్రతి గుంటలో ఒక ఆరోగ్యకరమైన మొక్క ఉంచాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Interculture', 'Keep crop weed-free for first 45-60 days and earth up rows.', 'మొదటి 45-60 రోజులు కలుపు లేకుండా ఉంచి వరుసలకు మట్టిని ఎగదీయాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Picking', 'Pick kapas during dry weather and keep clean cotton separate.', 'ఎండ వాతావరణంలో పత్తి ఏరి శుభ్రమైన పత్తిని విడిగా ఉంచాలి.');
INSERT INTO public.crop_fertilizers (crop_id, stage, fertilizer, quantity, method, description_te) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Basal', 'DAP + MOP + FYM', 'Soil-test based; part N and full P/K', 'Place near root zone before sowing', 'పత్తిలో Basal దశలో DAP + MOP + FYMను సిఫారసు ప్రకారం వాడాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), '30 DAS', 'Urea', 'First top dressing', 'Apply after weeding with moisture', 'పత్తిలో 30 DAS దశలో Ureaను సిఫారసు ప్రకారం వాడాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), '60 DAS', 'Urea + MOP', 'Second top dressing', 'Apply before flowering peak', 'పత్తిలో 60 DAS దశలో Urea + MOPను సిఫారసు ప్రకారం వాడాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Flowering', 'Boron or MgSO4', 'Deficiency based foliar spray', 'Spray during cool hours', 'పత్తిలో Flowering దశలో Boron or MgSO4ను సిఫారసు ప్రకారం వాడాలి.');
INSERT INTO public.crop_irrigation (crop_id, stage, recommendation_en, recommendation_te) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Squaring', 'Avoid severe stress during square formation.', 'పత్తి పంటలో Squaring దశలో తేమ ఒత్తిడి రాకుండా చూడాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Flowering', 'Critical for boll retention.', 'పత్తి పంటలో Flowering దశలో తేమ ఒత్తిడి రాకుండా చూడాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Boll Development', 'Irrigate if dry spell occurs, but avoid waterlogging.', 'పత్తి పంటలో Boll Development దశలో తేమ ఒత్తిడి రాకుండా చూడాలి.');
INSERT INTO public.crop_weeds (crop_id, scientific_name, weed_name, control_measure, herbicide, dose, image_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Trianthema portulacastrum', 'Horse purslane', 'Early hoeing and hand weeding', 'Pendimethalin 30 EC', '1.0-1.3 L/acre pre-emergence', '/images/cotton.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Parthenium hysterophorus', 'Congress grass', 'Remove before flowering and maintain field borders', 'Directed glyphosate on bunds only', 'Avoid crop contact', '/images/cotton.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Cyperus rotundus', 'Nut sedge', 'Repeated interculture and tuber exhaustion', 'Pyrithiobac sodium', 'Post-emergence label dose', '/images/cotton.jpg');
INSERT INTO public.crop_pests (crop_id, pest_name, scientific_name, symptoms, management, chemical_control, image_url, image_source_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Pink bollworm', 'Pectinophora gossypiella', 'Rosette flowers, bored bolls, damaged seed and stained lint.', 'Use pheromone traps, remove damaged bolls, terminate crop timely and follow refuge.', 'Emamectin benzoate 5 SG, Chlorantraniliprole 18.5 SC or Diflubenzuron 25 WP', 'https://agritech.tnau.ac.in/crop_protection/cotton/Pink%20BollWorm.png', 'https://agritech.tnau.ac.in/crop_protection/cotton/crop_prot_crop_insectpest%20_cotton_2.html'),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Whitefly', 'Bemisia tabaci', 'Yellowing, honeydew, sooty mould and leaf curl spread.', 'Avoid excess nitrogen, conserve natural enemies and use yellow sticky traps.', 'Pyriproxyfen, Diafenthiuron or Spiromesifen as advisory', 'https://agritech.tnau.ac.in/crop_protection/cotton/Whitefly%20damage.jpg', 'PJTAU crop PDFs supplied by user: F:/pjtsau crops');
INSERT INTO public.crop_diseases (crop_id, disease_name, causal_organism, symptoms, management, fungicide, image_url, image_source_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Alternaria leaf spot', 'Alternaria macrospora', 'Brown concentric leaf spots and defoliation.', 'Use healthy seed, remove debris and avoid moisture stress.', 'Mancozeb or Copper oxychloride', '/images/cotton.jpg', 'PJTAU crop PDFs supplied by user: F:/pjtsau crops'),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Bacterial blight', 'Xanthomonas citri pv. malvacearum', 'Angular leaf spots, black arm symptoms and boll lesions.', 'Use acid-delinted clean seed and tolerant varieties.', 'Streptocycline + Copper oxychloride where recommended', '/images/cotton.jpg', 'PJTAU crop PDFs supplied by user: F:/pjtsau crops');
INSERT INTO public.crop_deficiencies (crop_id, deficiency_name, nutrient, symptoms, correction, image_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Boron deficiency', 'Boron', 'Square shedding, cracked bolls and poor boll opening.', 'Foliar spray borax at recommended concentration.', '/images/cotton.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Magnesium deficiency', 'Magnesium', 'Interveinal chlorosis of older leaves turning reddish.', 'Spray magnesium sulphate in repeated low-dose sprays.', '/images/cotton.jpg');
INSERT INTO public.crop_advisories (crop_id, category, advisory_en, advisory_te, keywords) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Pre-sowing', 'Collect soil sample and plan fertilizer from soil-test values.', 'విత్తే ముందు నేల నమూనా తీసుకుని పరీక్ష ఆధారంగా ఎరువుల ప్రణాళిక చేయాలి.', ARRAY['cotton', 'pre-sowing', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Seed treatment', 'Use 1.5-2.0 kg hybrid seed/acre. Treat with fungicide and biofertilizer as advised; maintain refuge for Bt cotton.', 'విత్తన శుద్ధి తప్పనిసరిగా చేసి పత్తి పంటను ఆరోగ్యంగా ప్రారంభించాలి.', ARRAY['cotton', 'seed treatment', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'Weather risk', 'Do not spray pesticides during high wind, rain or peak heat.', 'గాలి ఎక్కువగా ఉన్నప్పుడు, వర్షం ఉన్నప్పుడు లేదా తీవ్రమైన ఎండలో మందులు పిచికారీ చేయకూడదు.', ARRAY['cotton', 'weather risk', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'IPM', 'Use cultural, mechanical and biological measures before chemical control.', 'రసాయన నియంత్రణకు ముందు సాగు, యాంత్రిక, జీవ నియంత్రణ పద్ధతులు పాటించాలి.', ARRAY['cotton', 'ipm', 'advisory']::text[]);
INSERT INTO public.crop_faqs (crop_id, question, answer, answer_te, category, keywords) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should I check this week? What is the best production system for Cotton?', 'Timely sowing, gap filling, early weed control, balanced nutrition and IPM for sucking pests and bollworms are critical.', 'పత్తి: పంట వివరాలు విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Crop Profile', ARRAY['profile', 'production', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should I check this week? Which soil is suitable for Cotton?', 'Deep black cotton soils with good moisture retention are best; avoid shallow and waterlogged soils.', 'పత్తి: నేల విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Soil', ARRAY['soil', 'land', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should I check this week? What climate does Cotton need?', 'Warm climate with bright sunshine during boll opening. Excess rain during boll maturity reduces lint quality.', 'పత్తి: వాతావరణం విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Climate', ARRAY['climate', 'weather', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should I check this week? What is the seed rate for Cotton?', 'Use 1.5-2.0 kg hybrid seed/acre. Treat with fungicide and biofertilizer as advised; maintain refuge for Bt cotton.', 'పత్తి: విత్తనం విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Seed', ARRAY['seed rate', 'seed treatment', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should I check this week? When and how should Cotton be sown?', 'Sow with monsoon onset on ridges or broad beds. Spacing varies by Bt hybrid, commonly 90 x 60 cm or wider.', 'పత్తి: విత్తడం విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Sowing', ARRAY['sowing', 'spacing', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should I check this week? How should fertilizer be applied in Cotton?', 'Basal: DAP + MOP + FYM Soil-test based; part N and full P/K; 30 DAS: Urea First top dressing; 60 DAS: Urea + MOP Second top dressing; Flowering: Boron or MgSO4 Deficiency based foliar spray', 'పత్తి: ఎరువులు విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Fertilizer', ARRAY['fertilizer', 'nutrients', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should I check this week? What are critical irrigation stages for Cotton?', 'Squaring: Avoid severe stress during square formation. Flowering: Critical for boll retention. Boll Development: Irrigate if dry spell occurs, but avoid waterlogging.', 'పత్తి: నీటి నిర్వహణ విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Irrigation', ARRAY['irrigation', 'water', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should I check this week? How are weeds managed in Cotton?', 'Horse purslane: Early hoeing and hand weeding; Congress grass: Remove before flowering and maintain field borders; Nut sedge: Repeated interculture and tuber exhaustion', 'పత్తి: కలుపు విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Weed', ARRAY['weed', 'herbicide', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should I check this week? Which major pests attack Cotton?', 'Pink bollworm: Rosette flowers, bored bolls, damaged seed and stained lint. Management: Use pheromone traps, remove damaged bolls, terminate crop timely and follow refuge. Whitefly: Yellowing, honeydew, sooty mould and leaf curl spread. Management: Avoid excess nitrogen, conserve natural enemies and use yellow sticky traps.', 'పత్తి: పురుగులు విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Pest', ARRAY['pest', 'ipm', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should I check this week? Which diseases are important in Cotton?', 'Alternaria leaf spot: Brown concentric leaf spots and defoliation. Management: Use healthy seed, remove debris and avoid moisture stress. Bacterial blight: Angular leaf spots, black arm symptoms and boll lesions. Management: Use acid-delinted clean seed and tolerant varieties.', 'పత్తి: తెగుళ్లు విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Disease', ARRAY['disease', 'fungicide', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should I check this week? What nutrient deficiencies are common in Cotton?', 'Boron deficiency: Square shedding, cracked bolls and poor boll opening. Correction: Foliar spray borax at recommended concentration. Magnesium deficiency: Interveinal chlorosis of older leaves turning reddish. Correction: Spray magnesium sulphate in repeated low-dose sprays.', 'పత్తి: లోప లక్షణాలు విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Deficiency', ARRAY['deficiency', 'nutrient', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should I check this week? When should Cotton be harvested?', 'Pick fully opened clean kapas in multiple pickings. Expected kapas yield is 8-15 q/acre depending on rainfall and hybrid.', 'పత్తి: కోత విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Harvest', ARRAY['harvest', 'yield', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should an Agriculture Officer advise? What is the best production system for Cotton?', 'Timely sowing, gap filling, early weed control, balanced nutrition and IPM for sucking pests and bollworms are critical.', 'పత్తి: పంట వివరాలు విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Crop Profile', ARRAY['profile', 'production', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should an Agriculture Officer advise? Which soil is suitable for Cotton?', 'Deep black cotton soils with good moisture retention are best; avoid shallow and waterlogged soils.', 'పత్తి: నేల విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Soil', ARRAY['soil', 'land', 'cotton', 'cotton']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Cotton'), 'What should an Agriculture Officer advise? What climate does Cotton need?', 'Warm climate with bright sunshine during boll opening. Excess rain during boll maturity reduces lint quality.', 'పత్తి: వాతావరణం విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.', 'Climate', ARRAY['climate', 'weather', 'cotton', 'cotton']::text[]),
