INSERT INTO public.crop_production (crop_id, category, description_en, description_te) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'Land Preparation', 'Open furrows for drainage in black soils and avoid compact seedbeds.', 'నల్లరేగడి భూముల్లో నీరు నిల్వ కాకుండా సాళ్లు ఏర్పాటు చేయాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'Sowing', 'Use line sowing and maintain proper spacing for branching.', 'కొమ్మలు విస్తరించడానికి సరైన దూరంతో వరుసల్లో విత్తాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'Interculture', 'Hoe at 25-30 and 45-50 DAS to conserve moisture and control weeds.', '25-30 మరియు 45-50 రోజుల దశలో కలుపు తీసి తేమ నిల్వ చేయాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'Harvest', 'Cut plants when pods are dry; thresh after sun drying.', 'కాయలు ఎండినప్పుడు మొక్కలను కోసి ఎండబెట్టి నూర్పిడి చేయాలి.');
