INSERT INTO public.crop_pests (crop_id, pest_name, scientific_name, symptoms, management, chemical_control, image_url, image_source_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'Gram pod borer', 'Helicoverpa armigera', 'Larva feeds with head inside pod; round holes and grain damage.', 'Use pheromone traps, bird perches, NPV, sunflower trap row and need-based sprays.', 'Emamectin benzoate 5 SG, Indoxacarb 15.8 SC, Chlorantraniliprole 18.5 SC or Spinosad 45 SC', 'https://agritech.tnau.ac.in/crop_protection/crop_prot_crop_insect_pul_red%20gram_clip_image002.jpg', 'https://agritech.tnau.ac.in/crop_protection/crop_prot_crop_insect_pul_red%20gram.html'),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'Pod fly', 'Melanagromyza obtusa', 'Maggot feeds inside developing seed; shrivelled grain.', 'Early sowing, collect damaged pods and avoid staggered flowering.', 'Dimethoate or Thiomethoxam as local advisory', '/images/pulses.jpg', 'PJTAU crop PDFs supplied by user: F:/pjtsau crops');
INSERT INTO public.crop_diseases (crop_id, disease_name, causal_organism, symptoms, management, fungicide, image_url, image_source_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'Wilt', 'Fusarium udum', 'Sudden wilting, brown vascular discoloration and plant death.', 'Use wilt tolerant variety, seed treatment and crop rotation.', 'Carbendazim seed treatment; Trichoderma in soil', '/images/pulses.jpg', 'PJTAU crop PDFs supplied by user: F:/pjtsau crops'),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'Sterility mosaic', 'Pigeonpea sterility mosaic virus', 'Bushy pale green plants with little or no flowering.', 'Use resistant varieties and control eriophyid mite vector.', 'Wettable sulphur or Dimethoate as advisory for mite', '/images/pulses.jpg', 'PJTAU crop PDFs supplied by user: F:/pjtsau crops');
