((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'Sulphur deficiency', 'Sulphur', 'Young leaves become pale and plants remain weak.', 'Apply gypsum or SSP based on soil test.', '/images/pulses.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'Iron chlorosis', 'Iron', 'Young leaves show interveinal chlorosis in calcareous soils.', 'Foliar spray ferrous sulphate with lime neutralization.', '/images/pulses.jpg');
INSERT INTO public.crop_advisories (crop_id, category, advisory_en, advisory_te, keywords) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'Pre-sowing', 'Collect soil sample and plan fertilizer from soil-test values.', 'విత్తే ముందు నేల నమూనా తీసుకుని పరీక్ష ఆధారంగా ఎరువుల ప్రణాళిక చేయాలి.', ARRAY['redgram', 'pre-sowing', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'Seed treatment', 'Use 4-6 kg seed/acre. Treat with fungicide, Rhizobium and PSB as recommended.', 'విత్తన శుద్ధి తప్పనిసరిగా చేసి కంది పంటను ఆరోగ్యంగా ప్రారంభించాలి.', ARRAY['redgram', 'seed treatment', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'Weather risk', 'Do not spray pesticides during high wind, rain or peak heat.', 'గాలి ఎక్కువగా ఉన్నప్పుడు, వర్షం ఉన్నప్పుడు లేదా తీవ్రమైన ఎండలో మందులు పిచికారీ చేయకూడదు.', ARRAY['redgram', 'weather risk', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'IPM', 'Use cultural, mechanical and biological measures before chemical control.', 'రసాయన నియంత్రణకు ముందు సాగు, యాంత్రిక, జీవ నియంత్రణ పద్ధతులు పాటించాలి.', ARRAY['redgram', 'ipm', 'advisory']::text[]);
INSERT INTO public.crop_faqs (crop_id, question, answer, answer_te, category, keywords) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'What should I check this week? What is the best production system for Redgram / Pigeonpea?', 'Timely sowing, seed inoculation, interculture, drainage and pod borer monitoring from flowering are essential.', 'కంది: పంట వివరాలు విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార పద్ధతుల్లో ఒంటరి పంటగా, అంతర పంటగా, సరిహద్దు పంటగా సాగు చేసే లోతైన వేర్ల పప్పుధాన్య పంట.', 'Crop Profile', ARRAY['profile', 'production', 'redgram', 'redgram / pigeonpea']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'What should I check this week? Which soil is suitable for Redgram / Pigeonpea?', 'Well-drained red sandy loams and medium black soils are suitable. Waterlogging causes wilt and root rot.', 'కంది: నేల విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార పద్ధతుల్లో ఒంటరి పంటగా, అంతర పంటగా, సరిహద్దు పంటగా సాగు చేసే లోతైన వేర్ల పప్పుధాన్య పంట.', 'Soil', ARRAY['soil', 'land', 'redgram', 'redgram / pigeonpea']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'What should I check this week? What climate does Redgram / Pigeonpea need?', 'Warm semi-arid climate; flowering and pod filling need mild weather and no prolonged moisture stress.', 'కంది: వాతావరణం విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార పద్ధతుల్లో ఒంటరి పంటగా, అంతర పంటగా, సరిహద్దు పంటగా సాగు చేసే లోతైన వేర్ల పప్పుధాన్య పంట.', 'Climate', ARRAY['climate', 'weather', 'redgram', 'redgram / pigeonpea']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'What should I check this week? What is the seed rate for Redgram / Pigeonpea?', 'Use 4-6 kg seed/acre. Treat with fungicide, Rhizobium and PSB as recommended.', 'కంది: విత్తనం విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార పద్ధతుల్లో ఒంటరి పంటగా, అంతర పంటగా, సరిహద్దు పంటగా సాగు చేసే లోతైన వేర్ల పప్పుధాన్య పంట.', 'Seed', ARRAY['seed rate', 'seed treatment', 'redgram', 'redgram / pigeonpea']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'What should I check this week? When and how should Redgram / Pigeonpea be sown?', 'Kharif sowing with monsoon onset; spacing 90 x 20 cm for long duration and closer for short duration types.', 'కంది: విత్తడం విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార పద్ధతుల్లో ఒంటరి పంటగా, అంతర పంటగా, సరిహద్దు పంటగా సాగు చేసే లోతైన వేర్ల పప్పుధాన్య పంట.', 'Sowing', ARRAY['sowing', 'spacing', 'redgram', 'redgram / pigeonpea']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'What should I check this week? How should fertilizer be applied in Redgram / Pigeonpea?', 'Basal: SSP or DAP + FYM Apply starter N and full P; Biofertilizer: Rhizobium + PSB One packet each per seed lot; Sulphur: Gypsum or SSP source Soil-test based; Flowering: Pulse wonder or 2% DAP As advisory', 'కంది: ఎరువులు విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార పద్ధతుల్లో ఒంటరి పంటగా, అంతర పంటగా, సరిహద్దు పంటగా సాగు చేసే లోతైన వేర్ల పప్పుధాన్య పంట.', 'Fertilizer', ARRAY['fertilizer', 'nutrients', 'redgram', 'redgram / pigeonpea']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'What should I check this week? What are critical irrigation stages for Redgram / Pigeonpea?', 'Establishment: Protect germination if monsoon break occurs. Flowering: One protective irrigation improves pod set in dry spell. Pod Filling: Avoid waterlogging; provide light irrigation only if needed.', 'కంది: నీటి నిర్వహణ విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార పద్ధతుల్లో ఒంటరి పంటగా, అంతర పంటగా, సరిహద్దు పంటగా సాగు చేసే లోతైన వేర్ల పప్పుధాన్య పంట.', 'Irrigation', ARRAY['irrigation', 'water', 'redgram', 'redgram / pigeonpea']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'What should I check this week? How are weeds managed in Redgram / Pigeonpea?', 'Congress grass: Remove before flowering and maintain borders; Bermuda grass: Repeated hoeing and rhizome removal; Dayflower: Hand weeding and interculture', 'కంది: కలుపు విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార పద్ధతుల్లో ఒంటరి పంటగా, అంతర పంటగా, సరిహద్దు పంటగా సాగు చేసే లోతైన వేర్ల పప్పుధాన్య పంట.', 'Weed', ARRAY['weed', 'herbicide', 'redgram', 'redgram / pigeonpea']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'What should I check this week? Which major pests attack Redgram / Pigeonpea?', 'Gram pod borer: Larva feeds with head inside pod; round holes and grain damage. Management: Use pheromone traps, bird perches, NPV, sunflower trap row and need-based sprays. Pod fly: Maggot feeds inside developing seed; shrivelled grain. Management: Early sowing, collect damaged pods and avoid staggered flowering.', 'కంది: పురుగులు విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార పద్ధతుల్లో ఒంటరి పంటగా, అంతర పంటగా, సరిహద్దు పంటగా సాగు చేసే లోతైన వేర్ల పప్పుధాన్య పంట.', 'Pest', ARRAY['pest', 'ipm', 'redgram', 'redgram / pigeonpea']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'What should I check this week? Which diseases are important in Redgram / Pigeonpea?', 'Wilt: Sudden wilting, brown vascular discoloration and plant death. Management: Use wilt tolerant variety, seed treatment and crop rotation. Sterility mosaic: Bushy pale green plants with little or no flowering. Management: Use resistant varieties and control eriophyid mite vector.', 'కంది: తెగుళ్లు విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార పద్ధతుల్లో ఒంటరి పంటగా, అంతర పంటగా, సరిహద్దు పంటగా సాగు చేసే లోతైన వేర్ల పప్పుధాన్య పంట.', 'Disease', ARRAY['disease', 'fungicide', 'redgram', 'redgram / pigeonpea']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'What should I check this week? What nutrient deficiencies are common in Redgram / Pigeonpea?', 'Sulphur deficiency: Young leaves become pale and plants remain weak. Correction: Apply gypsum or SSP based on soil test. Iron chlorosis: Young leaves show interveinal chlorosis in calcareous soils. Correction: Foliar spray ferrous sulphate with lime neutralization.', 'కంది: లోప లక్షణాలు విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార పద్ధతుల్లో ఒంటరి పంటగా, అంతర పంటగా, సరిహద్దు పంటగా సాగు చేసే లోతైన వేర్ల పప్పుధాన్య పంట.', 'Deficiency', ARRAY['deficiency', 'nutrient', 'redgram', 'redgram / pigeonpea']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Redgram'), 'What should I check this week? When should Redgram / Pigeonpea be harvested?', 'Harvest when 80% pods turn brown and dry. Expected grain yield is 5-8 q/acre in rainfed crop.', 'కంది: కోత విభాగంలో ఈ సిఫారసును పాటించాలి. వర్షాధార పద్ధతుల్లో ఒంటరి పంటగా, అంతర పంటగా, సరిహద్దు పంటగా సాగు చేసే లోతైన వేర్ల పప్పుధాన్య పంట.', 'Harvest', ARRAY['harvest', 'yield', 'redgram', 'redgram / pigeonpea']::text[]),
