INSERT INTO public.crop_production (crop_id, category, description_en, description_te) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Land Preparation', 'Prepare a fine seedbed and ensure drainage channels.', 'మెత్తని విత్తన మడిని సిద్ధం చేసి మురుగు నీటి కాలువలు ఏర్పాటు చేయాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Sowing', 'Use line sowing for easy interculture and plant protection.', 'మధ్య జోత మరియు రక్షణ చర్యలకు సులభంగా ఉండేలా వరుసల్లో విత్తాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Weeding', 'Keep crop weed-free up to 25-30 days.', '25-30 రోజుల వరకు కలుపు లేకుండా ఉంచాలి.'),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Harvest', 'Pick pods when mature to avoid shattering and weather damage.', 'కాయలు పక్వానికి వచ్చినప్పుడు ఏరి రాలిపోవడం, వర్ష నష్టం నివారించాలి.');
