INSERT INTO public.crop_weeds (crop_id, scientific_name, weed_name, control_measure, herbicide, dose, image_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Cyperus rotundus', 'Nut sedge', 'Early hand weeding and hoeing', 'Pendimethalin 30 EC', '0.75-1.0 L/acre pre-emergence', '/images/pulses.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Echinochloa colona', 'Jungle rice', 'Line sowing and interculture', 'Quizalofop ethyl', 'Post-emergence grass control', '/images/pulses.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Trianthema portulacastrum', 'Horse purslane', 'Remove before it spreads as mat', 'Imazethapyr', 'Use as locally recommended', '/images/pulses.jpg');
INSERT INTO public.crop_pests (crop_id, pest_name, scientific_name, symptoms, management, chemical_control, image_url, image_source_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Whitefly', 'Bemisia tabaci', 'Sucks sap and transmits yellow mosaic virus.', 'Use yellow sticky traps, remove infected plants and avoid late sowing.', 'Thiamethoxam or Acetamiprid as advisory', 'https://agritech.tnau.ac.in/crop_protection/green_gram_disease/yellow_mosaic_clip_image002.jpg', 'https://agritech.tnau.ac.in/crop_protection/green_gram_disease/yellow_mosaic.html'),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Spotted pod borer', 'Maruca vitrata', 'Webbed flowers and pods with larval feeding.', 'Monitor from flowering, remove webs and use need-based sprays.', 'Emamectin benzoate or Chlorantraniliprole', '/images/pulses.jpg', 'PJTAU crop PDFs supplied by user: F:/pjtsau crops');
INSERT INTO public.crop_diseases (crop_id, disease_name, causal_organism, symptoms, management, fungicide, image_url, image_source_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Yellow mosaic', 'Mungbean yellow mosaic virus', 'Yellow and green mosaic patches, stunting and few pods.', 'Use tolerant varieties, early sowing and manage whitefly vector.', 'No curative fungicide; vector control only', 'https://agritech.tnau.ac.in/crop_protection/green_gram_disease/yellow_mosaic_clip_image002.jpg', 'https://agritech.tnau.ac.in/crop_protection/green_gram_disease/yellow_mosaic.html'),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Powdery mildew', 'Erysiphe polygoni', 'White powdery growth on leaves and pods.', 'Avoid late humid crop and use tolerant varieties.', 'Wettable sulphur or Hexaconazole as advisory', '/images/pulses.jpg', 'PJTAU crop PDFs supplied by user: F:/pjtsau crops');
INSERT INTO public.crop_deficiencies (crop_id, deficiency_name, nutrient, symptoms, correction, image_url) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Sulphur deficiency', 'Sulphur', 'Pale young leaves and poor growth.', 'Apply sulphur source basally.', '/images/pulses.jpg'),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Molybdenum deficiency', 'Molybdenum', 'Poor nodulation and nitrogen fixation.', 'Use micronutrient seed coating where advised.', '/images/pulses.jpg');
INSERT INTO public.crop_advisories (crop_id, category, advisory_en, advisory_te, keywords) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Pre-sowing', 'Collect soil sample and plan fertilizer from soil-test values.', 'విత్తే ముందు నేల నమూనా తీసుకుని పరీక్ష ఆధారంగా ఎరువుల ప్రణాళిక చేయాలి.', ARRAY['greengram', 'pre-sowing', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Seed treatment', 'Use 6-8 kg seed/acre. Treat with fungicide, Rhizobium and PSB; use certified seed for yellow mosaic tolerance.', 'విత్తన శుద్ధి తప్పనిసరిగా చేసి పెసర పంటను ఆరోగ్యంగా ప్రారంభించాలి.', ARRAY['greengram', 'seed treatment', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'Weather risk', 'Do not spray pesticides during high wind, rain or peak heat.', 'గాలి ఎక్కువగా ఉన్నప్పుడు, వర్షం ఉన్నప్పుడు లేదా తీవ్రమైన ఎండలో మందులు పిచికారీ చేయకూడదు.', ARRAY['greengram', 'weather risk', 'advisory']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'IPM', 'Use cultural, mechanical and biological measures before chemical control.', 'రసాయన నియంత్రణకు ముందు సాగు, యాంత్రిక, జీవ నియంత్రణ పద్ధతులు పాటించాలి.', ARRAY['greengram', 'ipm', 'advisory']::text[]);
INSERT INTO public.crop_faqs (crop_id, question, answer, answer_te, category, keywords) VALUES
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'What should I check this week? What is the best production system for Greengram / Mungbean?', 'Direct line sowing, early weed-free period, drainage, whitefly monitoring and timely harvest reduce losses.', 'పెసర: పంట వివరాలు విభాగంలో ఈ సిఫారసును పాటించాలి. ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.', 'Crop Profile', ARRAY['profile', 'production', 'greengram', 'greengram / mungbean']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'What should I check this week? Which soil is suitable for Greengram / Mungbean?', 'Well-drained loamy soils with neutral pH are preferred. Avoid saline and waterlogged fields.', 'పెసర: నేల విభాగంలో ఈ సిఫారసును పాటించాలి. ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.', 'Soil', ARRAY['soil', 'land', 'greengram', 'greengram / mungbean']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'What should I check this week? What climate does Greengram / Mungbean need?', 'Warm weather crop. Cloudy humid weather increases yellow mosaic and powdery mildew risk.', 'పెసర: వాతావరణం విభాగంలో ఈ సిఫారసును పాటించాలి. ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.', 'Climate', ARRAY['climate', 'weather', 'greengram', 'greengram / mungbean']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'What should I check this week? What is the seed rate for Greengram / Mungbean?', 'Use 6-8 kg seed/acre. Treat with fungicide, Rhizobium and PSB; use certified seed for yellow mosaic tolerance.', 'పెసర: విత్తనం విభాగంలో ఈ సిఫారసును పాటించాలి. ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.', 'Seed', ARRAY['seed rate', 'seed treatment', 'greengram', 'greengram / mungbean']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'What should I check this week? When and how should Greengram / Mungbean be sown?', 'Line sow at 30 x 10 cm in a fine seedbed. Kharif sowing with rains; summer sowing under irrigation.', 'పెసర: విత్తడం విభాగంలో ఈ సిఫారసును పాటించాలి. ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.', 'Sowing', ARRAY['sowing', 'spacing', 'greengram', 'greengram / mungbean']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'What should I check this week? How should fertilizer be applied in Greengram / Mungbean?', 'Basal: DAP or SSP + MOP Starter N and full P/K; Biofertilizer: Rhizobium + PSB Seed treatment; Sulphur: Gypsum or bentonite sulphur Soil-test based; Flowering: 2% DAP or pulse special As advisory', 'పెసర: ఎరువులు విభాగంలో ఈ సిఫారసును పాటించాలి. ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.', 'Fertilizer', ARRAY['fertilizer', 'nutrients', 'greengram', 'greengram / mungbean']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'What should I check this week? What are critical irrigation stages for Greengram / Mungbean?', 'Germination: Light irrigation for summer sowing. Flowering: Avoid stress; waterlogging must be avoided. Pod Filling: One light irrigation may be useful in summer crop.', 'పెసర: నీటి నిర్వహణ విభాగంలో ఈ సిఫారసును పాటించాలి. ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.', 'Irrigation', ARRAY['irrigation', 'water', 'greengram', 'greengram / mungbean']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'What should I check this week? How are weeds managed in Greengram / Mungbean?', 'Nut sedge: Early hand weeding and hoeing; Jungle rice: Line sowing and interculture; Horse purslane: Remove before it spreads as mat', 'పెసర: కలుపు విభాగంలో ఈ సిఫారసును పాటించాలి. ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.', 'Weed', ARRAY['weed', 'herbicide', 'greengram', 'greengram / mungbean']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'What should I check this week? Which major pests attack Greengram / Mungbean?', 'Whitefly: Sucks sap and transmits yellow mosaic virus. Management: Use yellow sticky traps, remove infected plants and avoid late sowing. Spotted pod borer: Webbed flowers and pods with larval feeding. Management: Monitor from flowering, remove webs and use need-based sprays.', 'పెసర: పురుగులు విభాగంలో ఈ సిఫారసును పాటించాలి. ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.', 'Pest', ARRAY['pest', 'ipm', 'greengram', 'greengram / mungbean']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'What should I check this week? Which diseases are important in Greengram / Mungbean?', 'Yellow mosaic: Yellow and green mosaic patches, stunting and few pods. Management: Use tolerant varieties, early sowing and manage whitefly vector. Powdery mildew: White powdery growth on leaves and pods. Management: Avoid late humid crop and use tolerant varieties.', 'పెసర: తెగుళ్లు విభాగంలో ఈ సిఫారసును పాటించాలి. ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.', 'Disease', ARRAY['disease', 'fungicide', 'greengram', 'greengram / mungbean']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'What should I check this week? What nutrient deficiencies are common in Greengram / Mungbean?', 'Sulphur deficiency: Pale young leaves and poor growth. Correction: Apply sulphur source basally. Molybdenum deficiency: Poor nodulation and nitrogen fixation. Correction: Use micronutrient seed coating where advised.', 'పెసర: లోప లక్షణాలు విభాగంలో ఈ సిఫారసును పాటించాలి. ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.', 'Deficiency', ARRAY['deficiency', 'nutrient', 'greengram', 'greengram / mungbean']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'What should I check this week? When should Greengram / Mungbean be harvested?', 'Harvest mature pods in 1-2 pickings or whole plant when most pods turn black. Expected yield is 4-6 q/acre.', 'పెసర: కోత విభాగంలో ఈ సిఫారసును పాటించాలి. ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.', 'Harvest', ARRAY['harvest', 'yield', 'greengram', 'greengram / mungbean']::text[]),
((SELECT id FROM public.crops WHERE crop_name = 'Greengram'), 'What should an Agriculture Officer advise? What is the best production system for Greengram / Mungbean?', 'Direct line sowing, early weed-free period, drainage, whitefly monitoring and timely harvest reduce losses.', 'పెసర: పంట వివరాలు విభాగంలో ఈ సిఫారసును పాటించాలి. ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.', 'Crop Profile', ARRAY['profile', 'production', 'greengram', 'greengram / mungbean']::text[]),
