VALUES ('Paddy', 4400000, 'Major kharif and rabi food crop grown under transplanted, wet direct seeded and dry direct seeded systems.', '/images/paddy.jpg', 'paddy', 'Paddy / Rice', 'వరి', 'Oryza sativa', 'rice.pdf', '{"crop_profile":"Major kharif and rabi food crop grown under transplanted, wet direct seeded and dry direct seeded systems.","crop_profile_te":"నాట్లు, తడి నేరుగా విత్తడం, పొడి నేరుగా విత్తడం పద్ధతుల్లో సాగు చేసే ప్రధాన ఆహార పంట.","soil_requirements":"Clay loams and water-retentive fertile soils are preferred. Avoid saline, alkaline and poorly drained problem soils unless reclaimed.","climate_requirements":"Warm humid climate with reliable irrigation or rainfall. Sensitive to cold during flowering and grain filling.","sowing_time_spacing_land_preparation":"Nursery from late May to July based on water availability. Transplant at 20 x 15 cm or use line sowing in direct seeded fields after puddling or fine seedbed preparation.","seed_rate_seed_treatment":"Nursery seed 20-25 kg/acre; direct seeded rice 10-12 kg/acre. Treat seed with carbendazim or recommended bioagent and use salt-water seed selection where practiced.","crop_production_practices":"Raise healthy nursery, transplant young seedlings, maintain optimum plant population, use balanced nutrients and timely weed and pest monitoring.","harvesting_yield":"Harvest when 80-85% grains are mature and straw turns yellow. Expected yield is 25-35 q/acre depending on variety and water management.","deficiency_symptoms":"Zinc deficiency causes bronzing and stunted growth; nitrogen deficiency causes pale yellow older leaves; iron toxicity causes brown speckling in poorly drained acidic soils."}'::jsonb, now())
ON CONFLICT (crop_name) DO UPDATE SET acreage = EXCLUDED.acreage, description = EXCLUDED.description, image_url = EXCLUDED.image_url, slug = EXCLUDED.slug, name_en = EXCLUDED.name_en, name_te = EXCLUDED.name_te, scientific_name = EXCLUDED.scientific_name, source_pdf_name = EXCLUDED.source_pdf_name, profile = EXCLUDED.profile, updated_at = now();













VALUES ('Maize', 1400000, 'Cereal crop grown for grain, fodder, sweet corn and industrial use; hybrids dominate commercial production.', '/images/maize.jpg', 'maize', 'Maize', 'మొక్కజొన్న', 'Zea mays', 'maize.pdf', '{"crop_profile":"Cereal crop grown for grain, fodder, sweet corn and industrial use; hybrids dominate commercial production.","crop_profile_te":"ధాన్యం, పశుగ్రాసం, స్వీట్ కార్న్ మరియు పరిశ్రమల కోసం సాగు చేసే ముఖ్యమైన ధాన్య పంట.","soil_requirements":"Well-drained fertile loams and red sandy loams are ideal. Waterlogging seriously reduces stand and yield.","climate_requirements":"Warm climate with good sunlight. Critical moisture stages are knee high, tasseling, silking and grain filling.","sowing_time_spacing_land_preparation":"Sow with onset of monsoon or under irrigation. Use 60 x 20 cm spacing for grain maize; prepare ridges or well-drained beds.","seed_rate_seed_treatment":"Use 8-10 kg seed/acre for hybrids. Treat seed with recommended fungicide and fall armyworm seed treatment where advised.","crop_production_practices":"Direct line sowing, timely gap filling, earthing up, balanced fertilizer and early scouting for fall armyworm are essential.","harvesting_yield":"Harvest when husk turns dry and grain moisture falls. Expected grain yield is 25-35 q/acre in good hybrids.","deficiency_symptoms":"Nitrogen deficiency causes V-shaped yellowing of older leaves; zinc deficiency causes white bands near leaf base."}'::jsonb, now())
ON CONFLICT (crop_name) DO UPDATE SET acreage = EXCLUDED.acreage, description = EXCLUDED.description, image_url = EXCLUDED.image_url, slug = EXCLUDED.slug, name_en = EXCLUDED.name_en, name_te = EXCLUDED.name_te, scientific_name = EXCLUDED.scientific_name, source_pdf_name = EXCLUDED.source_pdf_name, profile = EXCLUDED.profile, updated_at = now();













VALUES ('Cotton', 1800000, 'Long duration fibre crop grown mainly under rainfed and irrigated black soil conditions.', '/images/cotton.jpg', 'cotton', 'Cotton', 'పత్తి', 'Gossypium hirsutum', 'cotton.pdf', '{"crop_profile":"Long duration fibre crop grown mainly under rainfed and irrigated black soil conditions.","crop_profile_te":"వర్షాధార మరియు సాగునీటి నల్లరేగడి భూముల్లో సాగు చేసే దీర్ఘకాలిక నార పంట.","soil_requirements":"Deep black cotton soils with good moisture retention are best; avoid shallow and waterlogged soils.","climate_requirements":"Warm climate with bright sunshine during boll opening. Excess rain during boll maturity reduces lint quality.","sowing_time_spacing_land_preparation":"Sow with monsoon onset on ridges or broad beds. Spacing varies by Bt hybrid, commonly 90 x 60 cm or wider.","seed_rate_seed_treatment":"Use 1.5-2.0 kg hybrid seed/acre. Treat with fungicide and biofertilizer as advised; maintain refuge for Bt cotton.","crop_production_practices":"Timely sowing, gap filling, early weed control, balanced nutrition and IPM for sucking pests and bollworms are critical.","harvesting_yield":"Pick fully opened clean kapas in multiple pickings. Expected kapas yield is 8-15 q/acre depending on rainfall and hybrid.","deficiency_symptoms":"Magnesium deficiency causes interveinal yellowing of older leaves; boron deficiency causes square and boll shedding."}'::jsonb, now())
ON CONFLICT (crop_name) DO UPDATE SET acreage = EXCLUDED.acreage, description = EXCLUDED.description, image_url = EXCLUDED.image_url, slug = EXCLUDED.slug, name_en = EXCLUDED.name_en, name_te = EXCLUDED.name_te, scientific_name = EXCLUDED.scientific_name, source_pdf_name = EXCLUDED.source_pdf_name, profile = EXCLUDED.profile, updated_at = now();













VALUES ('Redgram', 650000, 'Deep-rooted pulse crop grown as sole crop, intercrop and border crop in rainfed systems.', '/images/pulses.jpg', 'redgram', 'Redgram / Pigeonpea', 'కంది', 'Cajanus cajan', 'redgram.pdf', '{"crop_profile":"Deep-rooted pulse crop grown as sole crop, intercrop and border crop in rainfed systems.","crop_profile_te":"వర్షాధార పద్ధతుల్లో ఒంటరి పంటగా, అంతర పంటగా, సరిహద్దు పంటగా సాగు చేసే లోతైన వేర్ల పప్పుధాన్య పంట.","soil_requirements":"Well-drained red sandy loams and medium black soils are suitable. Waterlogging causes wilt and root rot.","climate_requirements":"Warm semi-arid climate; flowering and pod filling need mild weather and no prolonged moisture stress.","sowing_time_spacing_land_preparation":"Kharif sowing with monsoon onset; spacing 90 x 20 cm for long duration and closer for short duration types.","seed_rate_seed_treatment":"Use 4-6 kg seed/acre. Treat with fungicide, Rhizobium and PSB as recommended.","crop_production_practices":"Timely sowing, seed inoculation, interculture, drainage and pod borer monitoring from flowering are essential.","harvesting_yield":"Harvest when 80% pods turn brown and dry. Expected grain yield is 5-8 q/acre in rainfed crop.","deficiency_symptoms":"Sulphur deficiency causes uniform yellowing of young leaves; iron chlorosis may occur in calcareous soils."}'::jsonb, now())
ON CONFLICT (crop_name) DO UPDATE SET acreage = EXCLUDED.acreage, description = EXCLUDED.description, image_url = EXCLUDED.image_url, slug = EXCLUDED.slug, name_en = EXCLUDED.name_en, name_te = EXCLUDED.name_te, scientific_name = EXCLUDED.scientific_name, source_pdf_name = EXCLUDED.source_pdf_name, profile = EXCLUDED.profile, updated_at = now();













VALUES ('Greengram', 300000, 'Short duration pulse crop suitable for kharif, rabi and summer windows and as a catch crop.', '/images/greengram.webp', 'greengram', 'Greengram / Mungbean', 'పెసర', 'Vigna radiata', 'greengram.pdf', '{"crop_profile":"Short duration pulse crop suitable for kharif, rabi and summer windows and as a catch crop.","crop_profile_te":"ఖరీఫ్, రబీ, వేసవి కాలాలకు మరియు క్యాచ్ క్రాప్‌గా అనువైన స్వల్పకాలిక పప్పుధాన్య పంట.","soil_requirements":"Well-drained loamy soils with neutral pH are preferred. Avoid saline and waterlogged fields.","climate_requirements":"Warm weather crop. Cloudy humid weather increases yellow mosaic and powdery mildew risk.","sowing_time_spacing_land_preparation":"Line sow at 30 x 10 cm in a fine seedbed. Kharif sowing with rains; summer sowing under irrigation.","seed_rate_seed_treatment":"Use 6-8 kg seed/acre. Treat with fungicide, Rhizobium and PSB; use certified seed for yellow mosaic tolerance.","crop_production_practices":"Direct line sowing, early weed-free period, drainage, whitefly monitoring and timely harvest reduce losses.","harvesting_yield":"Harvest mature pods in 1-2 pickings or whole plant when most pods turn black. Expected yield is 4-6 q/acre.","deficiency_symptoms":"Molybdenum deficiency reduces nodulation; sulphur deficiency causes pale young leaves and poor seed protein."}'::jsonb, now())
ON CONFLICT (crop_name) DO UPDATE SET acreage = EXCLUDED.acreage, description = EXCLUDED.description, image_url = EXCLUDED.image_url, slug = EXCLUDED.slug, name_en = EXCLUDED.name_en, name_te = EXCLUDED.name_te, scientific_name = EXCLUDED.scientific_name, source_pdf_name = EXCLUDED.source_pdf_name, profile = EXCLUDED.profile, updated_at = now();













-- Backward-compatible consolidated table retained for existing CropPage reads.
CREATE TABLE IF NOT EXISTS public.crop_intelligence (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL UNIQUE,
  name_en text NOT NULL,
  name_te text NOT NULL,
  scientific_name text DEFAULT '',
  crop_image_url text DEFAULT '',
  source_pdf_name text DEFAULT '',
  source_pdf_url text DEFAULT '',
  content jsonb NOT NULL DEFAULT '{}'::jsonb,
  risks jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

VALUES ('paddy', 'Paddy / Rice', 'వరి', 'Oryza sativa', '/images/paddy.jpg', 'rice.pdf', '{"soil":{"en":"Clay loams and water-retentive fertile soils are preferred. Avoid saline, alkaline and poorly drained problem soils unless reclaimed.","te":"ఈ పంటకు Clay loams and water-retentive fertile soils are preferred. Avoid saline, alkaline and poorly drained problem soils unless reclaimed."},"duration":{"en":"120-125 days","te":"వరి పంట కాలం రకాన్ని బట్టి మారుతుంది."},"varieties":[{"name":"Telangana Sona (RNR 15048)","duration":"120-125 days","notes":{"en":"25-30 q/acre. Fine grain, low glycemic index, blast tolerant, suitable for Telangana conditions","te":"వరికు అనుకూలమైన సిఫారసు రకం."}},{"name":"Bathukamma (JGL 18047)","duration":"125 days","notes":{"en":"28-32 q/acre. Fine grain, good cooking quality, non-lodging type","te":"వరికు అనుకూలమైన సిఫారసు రకం."}},{"name":"Samba Mahsuri (BPT 5204)","duration":"145-150 days","notes":{"en":"25-30 q/acre. Popular fine grain, needs careful disease management","te":"వరికు అనుకూలమైన సిఫారసు రకం."}},{"name":"MTU 1010","duration":"120-125 days","notes":{"en":"25-32 q/acre. Short duration, suitable where water is limited","te":"వరికు అనుకూలమైన సిఫారసు రకం."}},{"name":"JGL 24423","duration":"130-135 days","notes":{"en":"28-34 q/acre. High yielding fine grain variety for irrigated ecology","te":"వరికు అనుకూలమైన సిఫారసు రకం."}}],"practices":[{"key":"soil","title":{"en":"Soil","te":"నేల"},"body":{"en":"Use level fields with bunds; avoid fields with severe salinity or alkalinity.","te":"సమతలంగా ఉన్న పొలాలు, బలమైన మెట్లు ఉండాలి; అధిక చౌడు లేదా క్షార భూములు నివారించాలి."}},{"key":"land_preparation","title":{"en":"Land Preparation","te":"Land Preparation"},"body":{"en":"Puddle thoroughly for transplanted paddy; for direct seeded rice prepare a fine, firm seedbed.","te":"నాట్ల వరికి మట్టిని బాగా కలియదున్నాలి; నేరుగా విత్తే పద్ధతికి మెత్తని గట్టి విత్తన మడిని సిద్ధం చేయాలి."}},{"key":"nursery","title":{"en":"Nursery","te":"Nursery"},"body":{"en":"Use clean seed, raised nursery beds and avoid over-aged seedlings.","te":"శుభ్రమైన విత్తనం, ఎత్తైన నారు మడులు వాడి, ముదురు నారు వాడకూడదు."}},{"key":"harvest","title":{"en":"Harvest","te":"కోత"},"body":{"en":"Drain water 7-10 days before harvest and dry grain to safe moisture.","te":"కోతకు 7-10 రోజుల ముందు నీరు వదిలి, ధాన్యాన్ని సురక్షిత తేమ వరకు ఆరబెట్టాలి."}}]}'::jsonb, '[{"type":"Pest","name":{"en":"Brown planthopper","te":"Brown planthopper"},"symptoms":{"en":"Nymphs and adults suck sap at plant base; hopper burn patches appear.","te":"Nymphs and adults suck sap at plant base; hopper burn patches appear."},"control":{"en":"Avoid excess nitrogen, drain briefly, conserve predators and spray above ETL.","te":"వరిలో ఈ పురుగు కనిపిస్తే సమగ్ర నియంత్రణ పాటించాలి."},"chemicals":["Pymetrozine 50 WG or Dinotefuran 20 SG as local advisory"],"newChemicals":[],"image_url":"https://agritech.tnau.ac.in/crop_protection/rice/images/pestc/ricenew/BPH/bph%20damage.jpg","image_source_url":"https://agritech.tnau.ac.in/expert_system/paddy/cppests_SB.html"},{"type":"Pest","name":{"en":"Yellow stem borer","te":"Yellow stem borer"},"symptoms":{"en":"Dead heart at vegetative stage and white ear at reproductive stage.","te":"Dead heart at vegetative stage and white ear at reproductive stage."},"control":{"en":"Clip seedling tips, remove stubbles, use pheromone traps and need-based insecticide.","te":"వరిలో ఈ పురుగు కనిపిస్తే సమగ్ర నియంత్రణ పాటించాలి."},"chemicals":["Chlorantraniliprole 18.5 SC or Cartap hydrochloride"],"newChemicals":[],"image_url":"https://agritech.tnau.ac.in/crop_protection/images/pestc/ricenew/stemborer/deadheart.jpg","image_source_url":"https://agritech.tnau.ac.in/expert_system/paddy/cppests_SB.html"},{"type":"Disease","name":{"en":"Blast","te":"Blast"},"symptoms":{"en":"Spindle-shaped grey lesions with brown margins; neck blast causes chaffy grains.","te":"Spindle-shaped grey lesions with brown margins; neck blast causes chaffy grains."},"control":{"en":"Use clean seed, balanced nitrogen, tolerant varieties and avoid dense canopy.","te":"వరిలో ఈ తెగులు కోసం శుభ్రమైన విత్తనం మరియు సిఫారసు మందు వాడాలి."},"chemicals":["Tricyclazole 75 WP or Azoxystrobin + Difenoconazole"],"newChemicals":[],"image_url":"https://agritech.tnau.ac.in/ta/crop_protection/images/crop_diseases/paddy/Blast_sym1.JPG","image_source_url":"https://www.agritech.tnau.ac.in/expert_system/paddy/cpdisblast.html"},{"type":"Disease","name":{"en":"Sheath blight","te":"Sheath blight"},"symptoms":{"en":"Oval lesions on sheath near water line that spread upward.","te":"Oval lesions on sheath near water line that spread upward."},"control":{"en":"Avoid excess nitrogen, maintain spacing and improve aeration.","te":"వరిలో ఈ తెగులు కోసం శుభ్రమైన విత్తనం మరియు సిఫారసు మందు వాడాలి."},"chemicals":["Hexaconazole or Validamycin as recommended"],"newChemicals":[],"image_url":"/images/paddy.jpg","image_source_url":"PJTAU crop PDFs supplied by user: F:/pjtsau crops"}]'::jsonb, now())
ON CONFLICT (slug) DO UPDATE SET name_en = EXCLUDED.name_en, name_te = EXCLUDED.name_te, scientific_name = EXCLUDED.scientific_name, crop_image_url = EXCLUDED.crop_image_url, source_pdf_name = EXCLUDED.source_pdf_name, content = EXCLUDED.content, risks = EXCLUDED.risks, updated_at = now();

VALUES ('maize', 'Maize', 'మొక్కజొన్న', 'Zea mays', '/images/maize.jpg', 'maize.pdf', '{"soil":{"en":"Well-drained fertile loams and red sandy loams are ideal. Waterlogging seriously reduces stand and yield.","te":"ఈ పంటకు Well-drained fertile loams and red sandy loams are ideal. Waterlogging seriously reduces stand and yield."},"duration":{"en":"90-95 days","te":"మొక్కజొన్న పంట కాలం రకాన్ని బట్టి మారుతుంది."},"varieties":[{"name":"DHM 111","duration":"90-95 days","notes":{"en":"25-30 q/acre. Tolerant to leaf blight and stalk rot; suitable for Telangana","te":"మొక్కజొన్నకు అనుకూలమైన సిఫారసు రకం."}},{"name":"DHM 117","duration":"95-100 days","notes":{"en":"30-35 q/acre. Orange flint grain, tolerant to stem borer and blights","te":"మొక్కజొన్నకు అనుకూలమైన సిఫారసు రకం."}},{"name":"DHM 121","duration":"90-95 days","notes":{"en":"30-35 q/acre. Short duration hybrid with good disease tolerance","te":"మొక్కజొన్నకు అనుకూలమైన సిఫారసు రకం."}},{"name":"Karimnagar Makka 1","duration":"95-100 days","notes":{"en":"30-35 q/acre. Tolerant to leaf blight and downy mildew","te":"మొక్కజొన్నకు అనుకూలమైన సిఫారసు రకం."}},{"name":"COH(M) 8 / local hybrid","duration":"95-110 days","notes":{"en":"30-38 q/acre. Use locally notified hybrid suited to season","te":"మొక్కజొన్నకు అనుకూలమైన సిఫారసు రకం."}}],"practices":[{"key":"land_preparation","title":{"en":"Land Preparation","te":"Land Preparation"},"body":{"en":"Prepare a fine seedbed with drainage furrows; avoid cloddy fields.","te":"మురుగు నీరు పోయేలా సాళ్లు చేసి మెత్తని విత్తన మడిని సిద్ధం చేయాలి."}},{"key":"sowing","title":{"en":"Sowing","te":"విత్తడం"},"body":{"en":"Place seed 4-5 cm deep in lines and maintain uniform plant stand.","te":"విత్తనాన్ని 4-5 సెం.మీ. లోతులో వరుసలలో వేసి సమాన మొక్కల సంఖ్య ఉంచాలి."}},{"key":"earthing_up","title":{"en":"Earthing Up","te":"Earthing Up"},"body":{"en":"Earth up at knee-high stage after top dressing nitrogen.","te":"మోకాలి ఎత్తు దశలో నత్రజని వేసిన తరువాత మట్టిని ఎగదీయాలి."}},{"key":"harvest","title":{"en":"Harvest","te":"కోత"},"body":{"en":"Harvest when cobs dry and black layer forms at grain base.","te":"కంకులు ఎండినప్పుడు, గింజ అడుగున బ్లాక్ లేయర్ ఏర్పడినప్పుడు కోత చేయాలి."}}]}'::jsonb, '[{"type":"Pest","name":{"en":"Fall armyworm","te":"Fall armyworm"},"symptoms":{"en":"Scraping, ragged holes, whorl feeding and frass in central whorl.","te":"Scraping, ragged holes, whorl feeding and frass in central whorl."},"control":{"en":"Install pheromone traps, destroy egg masses, direct spray into whorl at early stage.","te":"మొక్కజొన్నలో ఈ పురుగు కనిపిస్తే సమగ్ర నియంత్రణ పాటించాలి."},"chemicals":["Chlorantraniliprole 18.5 SC","Emamectin benzoate 5 SG or Spinetoram 11.7 SC"],"newChemicals":[],"image_url":"https://agritech.tnau.ac.in/crop_protection/maize/images/fallarmyworm/whorl%20damage.jpg","image_source_url":"https://agritech.tnau.ac.in/crop_protection/maize/crop_prot_maize_fall_armyworm.html"},{"type":"Pest","name":{"en":"Stem borer","te":"Stem borer"},"symptoms":{"en":"Dead hearts in young crop and stem tunneling.","te":"Dead hearts in young crop and stem tunneling."},"control":{"en":"Remove affected whorls, intercrop cowpea and use need-based whorl application.","te":"మొక్కజొన్నలో ఈ పురుగు కనిపిస్తే సమగ్ర నియంత్రణ పాటించాలి."},"chemicals":["Chlorantraniliprole or Carbofuran granules as permitted"],"newChemicals":[],"image_url":"https://agritech.tnau.ac.in/crop_protection/rice/images/pestc/maize/stemfly/deadheart.jpg","image_source_url":"https://agritech.tnau.ac.in/crop_protection/crop_prot_crop_insectpest%20_cereals_maizemain.html"},{"type":"Disease","name":{"en":"Turcicum leaf blight","te":"Turcicum leaf blight"},"symptoms":{"en":"Long grey-green cigar-shaped lesions on leaves.","te":"Long grey-green cigar-shaped lesions on leaves."},"control":{"en":"Use tolerant hybrids and remove infected residues.","te":"మొక్కజొన్నలో ఈ తెగులు కోసం శుభ్రమైన విత్తనం మరియు సిఫారసు మందు వాడాలి."},"chemicals":["Mancozeb or Propiconazole as advisory"],"newChemicals":[],"image_url":"/images/maize.jpg","image_source_url":"PJTAU crop PDFs supplied by user: F:/pjtsau crops"},{"type":"Disease","name":{"en":"Banded leaf and sheath blight","te":"Banded leaf and sheath blight"},"symptoms":{"en":"Banded lesions on sheath and lower leaves.","te":"Banded lesions on sheath and lower leaves."},"control":{"en":"Avoid dense planting and waterlogging.","te":"మొక్కజొన్నలో ఈ తెగులు కోసం శుభ్రమైన విత్తనం మరియు సిఫారసు మందు వాడాలి."},"chemicals":["Validamycin or Hexaconazole as recommended"],"newChemicals":[],"image_url":"/images/maize.jpg","image_source_url":"PJTAU crop PDFs supplied by user: F:/pjtsau crops"}]'::jsonb, now())
ON CONFLICT (slug) DO UPDATE SET name_en = EXCLUDED.name_en, name_te = EXCLUDED.name_te, scientific_name = EXCLUDED.scientific_name, crop_image_url = EXCLUDED.crop_image_url, source_pdf_name = EXCLUDED.source_pdf_name, content = EXCLUDED.content, risks = EXCLUDED.risks, updated_at = now();

VALUES ('cotton', 'Cotton', 'పత్తి', 'Gossypium hirsutum', '/images/cotton.jpg', 'cotton.pdf', '{"soil":{"en":"Deep black cotton soils with good moisture retention are best; avoid shallow and waterlogged soils.","te":"ఈ పంటకు Deep black cotton soils with good moisture retention are best; avoid shallow and waterlogged soils."},"duration":{"en":"160-170 days","te":"పత్తి పంట కాలం రకాన్ని బట్టి మారుతుంది."},"varieties":[{"name":"Narasimha (NA 1325)","duration":"160-170 days","notes":{"en":"8-12 q/acre kapas. Drought tolerant and jassid tolerant desi type","te":"పత్తికు అనుకూలమైన సిఫారసు రకం."}},{"name":"Srirama (NDLH 1938)","duration":"160-180 days","notes":{"en":"10-14 q/acre kapas. Robust rainfed variety with good boll setting","te":"పత్తికు అనుకూలమైన సిఫారసు రకం."}},{"name":"Bt hybrid - local notified","duration":"150-180 days","notes":{"en":"10-18 q/acre kapas. Use only notified hybrids suited to district and season","te":"పత్తికు అనుకూలమైన సిఫారసు రకం."}},{"name":"WGCV 48","duration":"160 days","notes":{"en":"8-12 q/acre kapas. Suitable for rainfed cotton areas","te":"పత్తికు అనుకూలమైన సిఫారసు రకం."}},{"name":"Suraj / compact cotton type","duration":"150-160 days","notes":{"en":"8-12 q/acre kapas. Suitable where high density planting is practiced","te":"పత్తికు అనుకూలమైన సిఫారసు రకం."}}],"practices":[{"key":"land_preparation","title":{"en":"Land Preparation","te":"Land Preparation"},"body":{"en":"Deep summer ploughing and broad bed furrow system improve drainage.","te":"లోతుగా వేసవి దున్నకం చేసి బ్రాడ్ బెడ్ ఫరో పద్ధతి వాడితే మురుగు నీరు బాగా పోతుంది."}},{"key":"sowing","title":{"en":"Sowing","te":"విత్తడం"},"body":{"en":"Sow after sufficient rainfall and maintain one healthy plant per hill.","te":"తగిన వర్షం తరువాత విత్తి ప్రతి గుంటలో ఒక ఆరోగ్యకరమైన మొక్క ఉంచాలి."}},{"key":"interculture","title":{"en":"Interculture","te":"Interculture"},"body":{"en":"Keep crop weed-free for first 45-60 days and earth up rows.","te":"మొదటి 45-60 రోజులు కలుపు లేకుండా ఉంచి వరుసలకు మట్టిని ఎగదీయాలి."}},{"key":"picking","title":{"en":"Picking","te":"Picking"},"body":{"en":"Pick kapas during dry weather and keep clean cotton separate.","te":"ఎండ వాతావరణంలో పత్తి ఏరి శుభ్రమైన పత్తిని విడిగా ఉంచాలి."}}]}'::jsonb, '[{"type":"Pest","name":{"en":"Pink bollworm","te":"Pink bollworm"},"symptoms":{"en":"Rosette flowers, bored bolls, damaged seed and stained lint.","te":"Rosette flowers, bored bolls, damaged seed and stained lint."},"control":{"en":"Use pheromone traps, remove damaged bolls, terminate crop timely and follow refuge.","te":"పత్తిలో ఈ పురుగు కనిపిస్తే సమగ్ర నియంత్రణ పాటించాలి."},"chemicals":["Emamectin benzoate 5 SG","Chlorantraniliprole 18.5 SC or Diflubenzuron 25 WP"],"newChemicals":[],"image_url":"https://agritech.tnau.ac.in/crop_protection/cotton/Pink%20BollWorm.png","image_source_url":"https://agritech.tnau.ac.in/crop_protection/cotton/crop_prot_crop_insectpest%20_cotton_2.html"},{"type":"Pest","name":{"en":"Whitefly","te":"Whitefly"},"symptoms":{"en":"Yellowing, honeydew, sooty mould and leaf curl spread.","te":"Yellowing, honeydew, sooty mould and leaf curl spread."},"control":{"en":"Avoid excess nitrogen, conserve natural enemies and use yellow sticky traps.","te":"పత్తిలో ఈ పురుగు కనిపిస్తే సమగ్ర నియంత్రణ పాటించాలి."},"chemicals":["Pyriproxyfen","Diafenthiuron or Spiromesifen as advisory"],"newChemicals":[],"image_url":"https://agritech.tnau.ac.in/crop_protection/cotton/Whitefly%20damage.jpg","image_source_url":"PJTAU crop PDFs supplied by user: F:/pjtsau crops"},{"type":"Disease","name":{"en":"Alternaria leaf spot","te":"Alternaria leaf spot"},"symptoms":{"en":"Brown concentric leaf spots and defoliation.","te":"Brown concentric leaf spots and defoliation."},"control":{"en":"Use healthy seed, remove debris and avoid moisture stress.","te":"పత్తిలో ఈ తెగులు కోసం శుభ్రమైన విత్తనం మరియు సిఫారసు మందు వాడాలి."},"chemicals":["Mancozeb or Copper oxychloride"],"newChemicals":[],"image_url":"/images/cotton.jpg","image_source_url":"PJTAU crop PDFs supplied by user: F:/pjtsau crops"},{"type":"Disease","name":{"en":"Bacterial blight","te":"Bacterial blight"},"symptoms":{"en":"Angular leaf spots, black arm symptoms and boll lesions.","te":"Angular leaf spots, black arm symptoms and boll lesions."},"control":{"en":"Use acid-delinted clean seed and tolerant varieties.","te":"పత్తిలో ఈ తెగులు కోసం శుభ్రమైన విత్తనం మరియు సిఫారసు మందు వాడాలి."},"chemicals":["Streptocycline + Copper oxychloride where recommended"],"newChemicals":[],"image_url":"/images/cotton.jpg","image_source_url":"PJTAU crop PDFs supplied by user: F:/pjtsau crops"}]'::jsonb, now())
ON CONFLICT (slug) DO UPDATE SET name_en = EXCLUDED.name_en, name_te = EXCLUDED.name_te, scientific_name = EXCLUDED.scientific_name, crop_image_url = EXCLUDED.crop_image_url, source_pdf_name = EXCLUDED.source_pdf_name, content = EXCLUDED.content, risks = EXCLUDED.risks, updated_at = now();

VALUES ('redgram', 'Redgram / Pigeonpea', 'కంది', 'Cajanus cajan', '/images/pulses.jpg', 'redgram.pdf', '{"soil":{"en":"Well-drained red sandy loams and medium black soils are suitable. Waterlogging causes wilt and root rot.","te":"ఈ పంటకు Well-drained red sandy loams and medium black soils are suitable. Waterlogging causes wilt and root rot."},"duration":{"en":"130-140 days","te":"కంది పంట కాలం రకాన్ని బట్టి మారుతుంది."},"varieties":[{"name":"PRG 176","duration":"130-140 days","notes":{"en":"6-8 q/acre. Suitable for rabi and short duration planting","te":"కందికు అనుకూలమైన సిఫారసు రకం."}},{"name":"LRG 41","duration":"160-180 days","notes":{"en":"5-8 q/acre. Popular variety suited to rainfed areas","te":"కందికు అనుకూలమైన సిఫారసు రకం."}},{"name":"Asha (ICPL 87119)","duration":"160-180 days","notes":{"en":"6-9 q/acre. Wilt tolerant and widely adapted","te":"కందికు అనుకూలమైన సిఫారసు రకం."}},{"name":"WRGE 97","duration":"150-160 days","notes":{"en":"6-8 q/acre. Suitable to medium soils","te":"కందికు అనుకూలమైన సిఫారసు రకం."}},{"name":"TS 3R","duration":"150-165 days","notes":{"en":"6-9 q/acre. Recommended where local seed is available","te":"కందికు అనుకూలమైన సిఫారసు రకం."}}],"practices":[{"key":"land_preparation","title":{"en":"Land Preparation","te":"Land Preparation"},"body":{"en":"Open furrows for drainage in black soils and avoid compact seedbeds.","te":"నల్లరేగడి భూముల్లో నీరు నిల్వ కాకుండా సాళ్లు ఏర్పాటు చేయాలి."}},{"key":"sowing","title":{"en":"Sowing","te":"విత్తడం"},"body":{"en":"Use line sowing and maintain proper spacing for branching.","te":"కొమ్మలు విస్తరించడానికి సరైన దూరంతో వరుసల్లో విత్తాలి."}},{"key":"interculture","title":{"en":"Interculture","te":"Interculture"},"body":{"en":"Hoe at 25-30 and 45-50 DAS to conserve moisture and control weeds.","te":"25-30 మరియు 45-50 రోజుల దశలో కలుపు తీసి తేమ నిల్వ చేయాలి."}},{"key":"harvest","title":{"en":"Harvest","te":"కోత"},"body":{"en":"Cut plants when pods are dry; thresh after sun drying.","te":"కాయలు ఎండినప్పుడు మొక్కలను కోసి ఎండబెట్టి నూర్పిడి చేయాలి."}}]}'::jsonb, '[{"type":"Pest","name":{"en":"Gram pod borer","te":"Gram pod borer"},"symptoms":{"en":"Larva feeds with head inside pod; round holes and grain damage.","te":"Larva feeds with head inside pod; round holes and grain damage."},"control":{"en":"Use pheromone traps, bird perches, NPV, sunflower trap row and need-based sprays.","te":"కందిలో ఈ పురుగు కనిపిస్తే సమగ్ర నియంత్రణ పాటించాలి."},"chemicals":["Emamectin benzoate 5 SG","Indoxacarb 15.8 SC","Chlorantraniliprole 18.5 SC or Spinosad 45 SC"],"newChemicals":[],"image_url":"https://agritech.tnau.ac.in/crop_protection/crop_prot_crop_insect_pul_red%20gram_clip_image002.jpg","image_source_url":"https://agritech.tnau.ac.in/crop_protection/crop_prot_crop_insect_pul_red%20gram.html"},{"type":"Pest","name":{"en":"Pod fly","te":"Pod fly"},"symptoms":{"en":"Maggot feeds inside developing seed; shrivelled grain.","te":"Maggot feeds inside developing seed; shrivelled grain."},"control":{"en":"Early sowing, collect damaged pods and avoid staggered flowering.","te":"కందిలో ఈ పురుగు కనిపిస్తే సమగ్ర నియంత్రణ పాటించాలి."},"chemicals":["Dimethoate or Thiomethoxam as local advisory"],"newChemicals":[],"image_url":"/images/pulses.jpg","image_source_url":"PJTAU crop PDFs supplied by user: F:/pjtsau crops"},{"type":"Disease","name":{"en":"Wilt","te":"Wilt"},"symptoms":{"en":"Sudden wilting, brown vascular discoloration and plant death.","te":"Sudden wilting, brown vascular discoloration and plant death."},"control":{"en":"Use wilt tolerant variety, seed treatment and crop rotation.","te":"కందిలో ఈ తెగులు కోసం శుభ్రమైన విత్తనం మరియు సిఫారసు మందు వాడాలి."},"chemicals":["Carbendazim seed treatment; Trichoderma in soil"],"newChemicals":[],"image_url":"/images/pulses.jpg","image_source_url":"PJTAU crop PDFs supplied by user: F:/pjtsau crops"},{"type":"Disease","name":{"en":"Sterility mosaic","te":"Sterility mosaic"},"symptoms":{"en":"Bushy pale green plants with little or no flowering.","te":"Bushy pale green plants with little or no flowering."},"control":{"en":"Use resistant varieties and control eriophyid mite vector.","te":"కందిలో ఈ తెగులు కోసం శుభ్రమైన విత్తనం మరియు సిఫారసు మందు వాడాలి."},"chemicals":["Wettable sulphur or Dimethoate as advisory for mite"],"newChemicals":[],"image_url":"/images/pulses.jpg","image_source_url":"PJTAU crop PDFs supplied by user: F:/pjtsau crops"}]'::jsonb, now())
ON CONFLICT (slug) DO UPDATE SET name_en = EXCLUDED.name_en, name_te = EXCLUDED.name_te, scientific_name = EXCLUDED.scientific_name, crop_image_url = EXCLUDED.crop_image_url, source_pdf_name = EXCLUDED.source_pdf_name, content = EXCLUDED.content, risks = EXCLUDED.risks, updated_at = now();

VALUES ('greengram', 'Greengram / Mungbean', 'పెసర', 'Vigna radiata', '/images/pulses.jpg', 'greengram.pdf', '{"soil":{"en":"Well-drained loamy soils with neutral pH are preferred. Avoid saline and waterlogged fields.","te":"ఈ పంటకు Well-drained loamy soils with neutral pH are preferred. Avoid saline and waterlogged fields."},"duration":{"en":"60-65 days","te":"పెసర పంట కాలం రకాన్ని బట్టి మారుతుంది."},"varieties":[{"name":"WGG 37 (Ekasila)","duration":"60-65 days","notes":{"en":"4-6 q/acre. Shiny green seed and tolerance to yellow mosaic","te":"పెసరకు అనుకూలమైన సిఫారసు రకం."}},{"name":"MGG 295","duration":"60-65 days","notes":{"en":"4-6 q/acre. Suitable for kharif and rabi seasons","te":"పెసరకు అనుకూలమైన సిఫారసు రకం."}},{"name":"VBN (Gg) 5","duration":"70-75 days","notes":{"en":"5-7 q/acre. High yielding, resistant to MYMV and leaf crinkle virus","te":"పెసరకు అనుకూలమైన సిఫారసు రకం."}},{"name":"LGG 460","duration":"65-70 days","notes":{"en":"4-6 q/acre. Bold seed and good market preference","te":"పెసరకు అనుకూలమైన సిఫారసు రకం."}},{"name":"IPM 2-14","duration":"65-70 days","notes":{"en":"4-6 q/acre. Yellow mosaic tolerant in many regions","te":"పెసరకు అనుకూలమైన సిఫారసు రకం."}}],"practices":[{"key":"land_preparation","title":{"en":"Land Preparation","te":"Land Preparation"},"body":{"en":"Prepare a fine seedbed and ensure drainage channels.","te":"మెత్తని విత్తన మడిని సిద్ధం చేసి మురుగు నీటి కాలువలు ఏర్పాటు చేయాలి."}},{"key":"sowing","title":{"en":"Sowing","te":"విత్తడం"},"body":{"en":"Use line sowing for easy interculture and plant protection.","te":"మధ్య జోత మరియు రక్షణ చర్యలకు సులభంగా ఉండేలా వరుసల్లో విత్తాలి."}},{"key":"weeding","title":{"en":"Weeding","te":"Weeding"},"body":{"en":"Keep crop weed-free up to 25-30 days.","te":"25-30 రోజుల వరకు కలుపు లేకుండా ఉంచాలి."}},{"key":"harvest","title":{"en":"Harvest","te":"కోత"},"body":{"en":"Pick pods when mature to avoid shattering and weather damage.","te":"కాయలు పక్వానికి వచ్చినప్పుడు ఏరి రాలిపోవడం, వర్ష నష్టం నివారించాలి."}}]}'::jsonb, '[{"type":"Pest","name":{"en":"Whitefly","te":"Whitefly"},"symptoms":{"en":"Sucks sap and transmits yellow mosaic virus.","te":"Sucks sap and transmits yellow mosaic virus."},"control":{"en":"Use yellow sticky traps, remove infected plants and avoid late sowing.","te":"పెసరలో ఈ పురుగు కనిపిస్తే సమగ్ర నియంత్రణ పాటించాలి."},"chemicals":["Thiamethoxam or Acetamiprid as advisory"],"newChemicals":[],"image_url":"https://agritech.tnau.ac.in/crop_protection/green_gram_disease/yellow_mosaic_clip_image002.jpg","image_source_url":"https://agritech.tnau.ac.in/crop_protection/green_gram_disease/yellow_mosaic.html"},{"type":"Pest","name":{"en":"Spotted pod borer","te":"Spotted pod borer"},"symptoms":{"en":"Webbed flowers and pods with larval feeding.","te":"Webbed flowers and pods with larval feeding."},"control":{"en":"Monitor from flowering, remove webs and use need-based sprays.","te":"పెసరలో ఈ పురుగు కనిపిస్తే సమగ్ర నియంత్రణ పాటించాలి."},"chemicals":["Emamectin benzoate or Chlorantraniliprole"],"newChemicals":[],"image_url":"/images/pulses.jpg","image_source_url":"PJTAU crop PDFs supplied by user: F:/pjtsau crops"},{"type":"Disease","name":{"en":"Yellow mosaic","te":"Yellow mosaic"},"symptoms":{"en":"Yellow and green mosaic patches, stunting and few pods.","te":"Yellow and green mosaic patches, stunting and few pods."},"control":{"en":"Use tolerant varieties, early sowing and manage whitefly vector.","te":"పెసరలో ఈ తెగులు కోసం శుభ్రమైన విత్తనం మరియు సిఫారసు మందు వాడాలి."},"chemicals":["No curative fungicide; vector control only"],"newChemicals":[],"image_url":"https://agritech.tnau.ac.in/crop_protection/green_gram_disease/yellow_mosaic_clip_image002.jpg","image_source_url":"https://agritech.tnau.ac.in/crop_protection/green_gram_disease/yellow_mosaic.html"},{"type":"Disease","name":{"en":"Powdery mildew","te":"Powdery mildew"},"symptoms":{"en":"White powdery growth on leaves and pods.","te":"White powdery growth on leaves and pods."},"control":{"en":"Avoid late humid crop and use tolerant varieties.","te":"పెసరలో ఈ తెగులు కోసం శుభ్రమైన విత్తనం మరియు సిఫారసు మందు వాడాలి."},"chemicals":["Wettable sulphur or Hexaconazole as advisory"],"newChemicals":[],"image_url":"/images/pulses.jpg","image_source_url":"PJTAU crop PDFs supplied by user: F:/pjtsau crops"}]'::jsonb, now())
ON CONFLICT (slug) DO UPDATE SET name_en = EXCLUDED.name_en, name_te = EXCLUDED.name_te, scientific_name = EXCLUDED.scientific_name, crop_image_url = EXCLUDED.crop_image_url, source_pdf_name = EXCLUDED.source_pdf_name, content = EXCLUDED.content, risks = EXCLUDED.risks, updated_at = now();
